INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$internal-admin-dashboard$j$,
  1,
  'PUBLISHED',
  $j$Internal Admin Dashboard$j$,
  1,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$Support staff use an internal dashboard all day to look up customer records and order history. It's not customer-facing and the traffic isn't spiky — but infra spend on internal tools gets scrutinized just as closely as anything public, and a dashboard that hangs mid-lookup is still a real support-team productivity problem. Engineering's job is the most basic one there is: size the service correctly for the traffic it actually gets, without overpaying for capacity nobody needs.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":350}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":350}$j$::jsonb,
  10000,
  900,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of lookups succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":150,"label":"95% of lookups complete within 150ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  750,
  FALSE,
  $j$["The Client's request rate is fixed at 350 req/s. What's a default API Server and Database's own raw throughput ceiling, at their default settings — does it actually clear 350 req/s?","Dropping default-configured components onto the canvas and connecting them isn't automatically enough. Most requests succeed eventually — so if success rate looks fine, what's actually failing?","Is there a cheaper way to hit the same latency bar than just cranking every dial as high as it'll go?"]$j$::jsonb,
  $j$["A connection pool's throughput ceiling is connections × (1000 / processing time) — a number you calculate, not one that takes care of itself at default settings.","Success rate alone doesn't tell the whole story — a backend can eventually process almost everything and still fail a real latency bar under queueing delay.","Budget makes 'just add more capacity' a real tradeoff, not a free move — the same latency bar is reachable at wildly different costs."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A modestly, deliberately sized API Server and Database — no cache, no special database type, no queue. Just enough capacity to clear the latency bar, no more.","editorial":["This scenario doesn't have a hidden trick — it's the most basic version of the lesson every other scenario in this catalogue builds on. A default API Server and Database's raw throughput ceiling sits right at the edge of what 350 req/s actually demands, so even though almost every request eventually gets a response, the queueing delay on the way there is enough to blow a real latency bar.","Fixing it doesn't require anything exotic — raising the Database's connection count and the API Server's own concurrency a modest amount clears both the success-rate and latency constraints comfortably.","The one real tradeoff left is cost: this traffic's own volume bills a fixed usage cost no matter how the pools are sized, so tightening the configuration further saves some money but not a dramatic amount — the real, avoidable waste is turning every dial up far higher than the traffic ever needed, which clears the metrics just as well while costing twice as much."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":350}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"maxConcurrent":6,"maxQueueLength":40,"processingTimeMs":3}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"maxConnections":6,"maxQueueLength":40,"processingTimeMs":6}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$url-shortener$j$,
  1,
  'PUBLISHED',
  $j$URL Shortener$j$,
  1,
  $j$["caching","system-design"]$j$::jsonb,
  NULL,
  $j$A link-shortening service is popular because of a handful of viral posts — the same few short links get clicked millions of times, while the long tail barely gets touched at all. Engineering's job is to design a resolution service that keeps up with that traffic, on a budget that won't get laughed out of a planning meeting.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":400,"keyPoolSize":30}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":400}$j$::jsonb,
  8000,
  200,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of lookups succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":100,"label":"95% of requests complete within 100ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  1400,
  FALSE,
  $j$["Drop an unconfigured API Server and Database on the canvas and wire them up. What's a default Database's own raw ceiling (connections x 1000/query time) against 400 req/s?","You can raise the Database's Max Connections to clear that ceiling — but watch the Budget row as you do. What does it cost by the time it clears 400 req/s?","How many distinct keys are actually being requested? Check the Client's Key Pool Size in the Inspector — does the traffic look like 400 truly unique lookups a second, or the same handful repeating?","Is there a component in the library whose entire job is to remember an answer instead of recomputing it — and where would it need to sit to keep expensive lookups from ever reaching the database at all?"]$j$::jsonb,
  $j$["A small, skewed set of hot keys is exactly what a cache is for — most 'repeated work' is really the same few keys, over and over.","A connection pool's throughput ceiling is a number you design for — an unconfigured default database falls short of real traffic before you've made a single decision.","Caching moves load off a bottleneck without touching its capacity — and because usage cost is billed per request that actually reaches a priced entity, cutting real request volume is a cost lever raw sizing alone can't match."]$j$::jsonb,
  $j${"prompt":"The Client sends a fixed 400 req/s for the whole run. A default, unconfigured Database (5 connections, 15ms per query) has a raw ceiling of connections x (1000/query time). Does that clear 400 req/s?","worked":"5 connections x (1000/15ms) = 333 req/s — already short of the 400 req/s arriving, on average, before a single burst is considered. An unconfigured Database isn't a neutral starting point here; it's already undersized. Raising Max Connections closes that gap, but every connection is billed whether or not it's ever used — a pool sized for raw capacity alone gets expensive fast. With only 30 distinct keys actually being requested, most of that traffic is answering the same question over and over — a much cheaper thing to fix than buying more connections."}$j$::jsonb,
  $j${"template":"This run landed at {{successRate}} success, {{throughput}} completed, and a p95 latency of {{p95Latency}} — but those numbers alone don't say whether you solved this well or just expensively. Check the Budget row and star rating above: the same success rate is reachable anywhere from a tightly-sized, cache-fronted build for a few hundred dollars a month to well over a thousand just by buying more database connections. With traffic this concentrated on a small set of keys, a cache absorbing repeat lookups is the cheaper win — raw sizing alone plateaus long before it gets there."}$j$::jsonb,
  $j${"summary":"A cache sized to hold the Client's entire key pool — so nearly every request is answered without ever reaching the database — in front of a minimally-sized pool underneath it.","editorial":["The traffic here is deliberately skewed: a handful of viral links get clicked far more than everything else combined. That skew is exactly what a cache is built for — a small cache can absorb a disproportionate share of requests when the traffic itself is this lopsided.","Raw sizing alone (a bigger API Server, a bigger database connection pool, tighter processing times) plateaus quickly. It can get an unconfigured build to pass, but it can't touch the real cost driver: this app's pricing bills per request that actually reaches the database, and sizing alone never reduces how many requests that is.","A cache in front of the database — sized to hold the full key pool, so essentially every hot link is a cache hit — cuts the *volume* of requests reaching the database, which is the lever raw sizing can't pull. That's what separates the 2-star and 3-star builds here: same functional shape, meaningfully cheaper once the cache is doing its job.","A tempting shortcut that doesn't actually solve this scenario: skipping the API Server and wiring the Client straight to the Cache/Database. It looks cheaper on paper, but it isn't a real architecture — production traffic never reaches a database directly without an application tier in front of it, which is why this app's scoring explicitly rejects any build shaped that way, no matter how well it scores otherwise."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":400,"keyPoolSize":30}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":5,"maxQueueLength":20,"processingTimeMs":1}},{"id":"cache","type":"cache","label":"Cache","position":{"x":600,"y":200},"config":{"capacity":30,"evictionPolicy":"lru","ttlMs":0}},{"id":"database","type":"database","label":"Database","position":{"x":860,"y":200},"config":{"maxConnections":1,"maxQueueLength":15,"processingTimeMs":1,"failureProbability":0}}],"connections":[{"source":"client","target":"api","latencyMs":5},{"source":"api","target":"cache","latencyMs":5},{"source":"cache","target":"database","latencyMs":5}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$recipe-of-the-day$j$,
  1,
  'PUBLISHED',
  $j$Recipe of the Day$j$,
  1,
  $j$["caching"]$j$::jsonb,
  NULL,
  $j$A cooking app features one 'Recipe of the Day' on its home screen — the same recipe, shown to every single user who opens the app. It's popular precisely because it's the same page for everyone, which means the database is answering the exact same question, over and over, for every user who checks the app that day. Engineering's job is to serve that one busy page without paying to re-fetch it from the database every single time.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":220,"keyPoolSize":30}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":220}$j$::jsonb,
  8000,
  980,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of page loads succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":100,"label":"95% of page loads complete within 100ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  450,
  FALSE,
  $j$["A properly-sized API Server and Database, with no cache at all, already clears both the success-rate and latency bars. Check what it costs against the budget.","Nearly every request is asking for the exact same recipe. What does that mean for how often the database actually needs to answer it?","The full set of recipes this app could show is small enough to hold entirely in a modest cache."]$j$::jsonb,
  $j$["A cache absorbs the most benefit when traffic is skewed toward a small set of hot keys — a single 'featured' item, viewed by everyone, is the most skewed case there is.","A functionally correct, properly-sized build can still fail a budget — a cheaper shape that does less repeat work isn't just cleverer, it can be required.","A cache sized to hold the full hot set turns nearly every request into a hit, collapsing the database's real workload down to almost nothing."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A modest cache holding the small set of possible daily recipes — so virtually every page load is answered without touching the database — in front of a minimally-sized database.","editorial":["A properly-sized API Server and Database, with no cache at all, already handles this traffic just fine functionally — the problem here is purely cost. Doing real database work for the same repeated question, over and over, adds up fast.","A cache sized to hold the small set of possible daily recipes turns almost every request into a hit. Once that's true, the database behind it barely needs to do anything — its own sizing (and its cost) collapses along with the volume actually reaching it.","This is about as skewed as traffic ever gets — a single featured item, shown to everyone — which is exactly the shape a cache is built for."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":220,"keyPoolSize":30}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":4,"maxQueueLength":30,"processingTimeMs":2}},{"id":"cache","type":"cache","label":"Cache","position":{"x":600,"y":200},"config":{"capacity":30,"evictionPolicy":"lru","ttlMs":0}},{"id":"db","type":"database","label":"Database","position":{"x":860,"y":200},"config":{"maxConnections":2,"maxQueueLength":20,"processingTimeMs":3}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"cache"},{"source":"cache","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$newsletter-send-confirmations$j$,
  1,
  'PUBLISHED',
  $j$Newsletter Send Confirmations$j$,
  1,
  $j$["message-queues"]$j$::jsonb,
  NULL,
  $j$A newsletter tool sends out a batch of emails whenever an editor hits 'publish' — a small flurry of send requests all at once, then quiet until the next issue goes out. Every send needs a confirmation logged, but nobody's staring at a loading spinner waiting for it. Engineering's job is to record every send reliably, without over-provisioning a backend that's idle most of the time.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":30}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"burst","rate":150,"duration":200,"interval":5000}$j$::jsonb,
  15000,
  990,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of sends are confirmed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":250,"label":"95% of confirmations arrive within 250ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  350,
  FALSE,
  $j$["Sends don't trickle in — every batch fires at once, right when an editor publishes. Watch what a Database's own backlog does with that.","A properly-sized synchronous build (Database sized generously, no queue) already passes here. Is there a shape that does the same job for less?","A Message Queue confirms a send the instant it's durably queued, rather than making the caller wait through the database's own backlog."]$j$::jsonb,
  $j$["A synchronous backend can pass a burst scenario on raw capacity alone — a Message Queue isn't always strictly required, but it's often the cheaper, faster way to get there.","A Message Queue confirms a request the instant it's durably admitted, decoupling the caller's wait from how long the actual downstream write takes.","Comparing a few different passing shapes side by side is worth doing — 'it passes' and 'it's the best passing shape' aren't the same question."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A Message Queue between the API Server and Database, confirming every send the instant it's durably queued — cheaper and faster than sizing the Database alone to absorb the burst.","editorial":["A synchronous build already passes here if the Database's backlog is generous enough — this scenario doesn't strictly require a queue the way some of the others do. But it's worth checking what that passing build actually costs.","Sizing the Database's connections up instead of just its backlog gets better latency, but costs noticeably more — you're paying for enough raw throughput to drain a burst almost instantly, most of which sits idle between publishes.","A Message Queue confirms the send the instant it's durably queued, regardless of how long the eventual database write takes. The Database behind it only needs to keep up with the sustained average rate — cheaper AND faster than either synchronous option."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":30}},{"id":"api","type":"api","label":"API Server","position":{"x":320,"y":200},"config":{"maxConcurrent":8,"maxQueueLength":80,"processingTimeMs":1}},{"id":"mq","type":"message_queue","label":"Message Queue","position":{"x":560,"y":200},"config":{"consumerCount":5,"maxQueueLength":150,"dispatchTimeMs":1}},{"id":"db","type":"database","label":"Database","position":{"x":800,"y":200},"config":{"maxConnections":1,"maxQueueLength":30,"processingTimeMs":1}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"mq"},{"source":"mq","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$movie-ticket-booking$j$,
  1,
  'PUBLISHED',
  $j$Movie Ticket Booking$j$,
  2,
  $j$["caching","system-design"]$j$::jsonb,
  NULL,
  $j$A movie theater chain is about to open ticket sales for a blockbuster release. Thousands of fans will hit the booking page the instant sales go live, all trying to reserve seats for the same few showtimes within seconds of each other. The demand itself is fixed — engineering's job is to design a booking service that actually serves it, on a budget that won't get laughed out of a planning meeting.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":370}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":370}$j$::jsonb,
  10000,
  100,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of booking requests succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":300,"label":"95% of requests complete within 300ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  1100,
  FALSE,
  $j$["The Client's request rate is fixed at 370 req/s — you can't design your way out of it. What actually determines how much of that a database connection pool can drain, before you touch a single other setting?","Dropping default-configured components onto the canvas and connecting them isn't the same as sizing them for this traffic. What's a default Database's own raw ceiling, at its default connection count and query time — does it even clear 370 req/s on paper?","Two builds can both clear the success-rate bar — one for a few hundred dollars a month, one for well over a thousand. What's the expensive one actually buying that the cheap one isn't?","Is there a cheaper way to keep repeat lookups from ever reaching the database at all?"]$j$::jsonb,
  $j$["A connection pool's throughput ceiling is connections × (1000 / processing time) — a number you design for, not one that takes care of itself at default settings.","Budget turns 'just add more capacity' from a free move into a real tradeoff — the same success rate is reachable at wildly different costs.","Efficient sizing (or a cache absorbing repeat work) beats brute-force overprovisioning, and it's the cheaper win, not just the cleverer one."]$j$::jsonb,
  $j${"prompt":"The Client will send a fixed 370 req/s for the whole run. If your Database has N connections and each query takes T ms, its raw ceiling is N × (1000/T) req/s. A default, unconfigured Database (5 connections, 15ms per query) — what's its ceiling, and does it even average out to 370 req/s on paper, before bursts are considered at all?","worked":"5 connections × (1000/15ms) = 333 req/s — already short of the 370 req/s arriving, on average, before a single burst is accounted for. Dropping default-configured components onto the canvas isn't a neutral starting point here; it's already an undersized one. Real traffic arrives in bursts, not evenly spaced, so a pool sized to just barely clear (or fall short of) the average has nowhere for those bursts to go but the queue, then rejection. A pool with real headroom — a raw ceiling meaningfully above 370, not just at or under it — is what actually survives contact with real traffic."}$j$::jsonb,
  $j${"template":"This run landed at {{successRate}} success, {{throughput}} completed, and a p95 latency of {{p95Latency}} — but those numbers alone don't say whether you solved this well or just expensively. Check the Budget row and star rating above: the exact same success rate is reachable anywhere from a few hundred dollars a month (a tightly sized pool, or a cache absorbing repeat lookups before they ever reach the database) to well over a thousand (just buying more of everything). Cost is the tell for which one you actually built."}$j$::jsonb,
  $j${"summary":"A cache sized to hold the Client's entire key pool — so nearly every request is answered without ever reaching the database — in front of a minimally-sized pool underneath it.","editorial":["Left completely unconfigured, this architecture doesn't fail on cost — it fails on raw capacity. A default API Server and Database can only push about 333 requests per second through them; the traffic this scenario hands you is higher than that. No amount of budget saves an architecture that can't physically keep up.","The fix isn't 'turn every dial up' — that clears the capacity bar but blows the budget by more than 2x. Sizing the API Server and Database properly (not maximally) already gets you a passing, 2-star build for a fraction of the cost.","The real lever is a Cache in front of the Database, sized to hold the Client's whole key pool. Once nearly every request can be answered from cache, the Database barely needs to be touched at all — its own sizing (and its cost) collapses along with the traffic actually reaching it. That's the 3-star shape: not bigger components, fewer requests reaching the expensive one.","A common near-miss: sizing the cache too small. If it can't hold the full key pool, a meaningful slice of traffic still falls through to the database on every run, and you're back to paying for capacity you thought the cache had already solved."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":370}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":5,"maxQueueLength":20,"processingTimeMs":1}},{"id":"cache","type":"cache","label":"Cache","position":{"x":600,"y":200},"config":{"capacity":50,"evictionPolicy":"lru","ttlMs":10000}},{"id":"database","type":"database","label":"Database","position":{"x":860,"y":200},"config":{"maxConnections":2,"maxQueueLength":15,"processingTimeMs":1,"failureProbability":0}}],"connections":[{"source":"client","target":"api","latencyMs":5},{"source":"api","target":"cache","latencyMs":5},{"source":"cache","target":"database","latencyMs":5}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$trending-hashtags-feed$j$,
  1,
  'PUBLISHED',
  $j$Trending Hashtags Feed$j$,
  2,
  $j$["caching"]$j$::jsonb,
  NULL,
  $j$A social app shows every user a 'Trending' feed of the day's hottest hashtags. It's the single most-viewed screen in the whole app — nearly everyone checks it, but they're all looking at the same handful of tags at any given moment. Engineering's job is to keep that screen fast for everyone hitting refresh, without paying to re-fetch the same handful of trending tags from the database over and over.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":300,"keyPoolSize":40}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":300}$j$::jsonb,
  8000,
  910,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of feed loads succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":80,"label":"95% of feed loads complete within 80ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  600,
  FALSE,
  $j$["Nearly everyone is looking at the same handful of trending tags at once. What does that mean for how often the database actually needs to be asked the same question?","A properly-sized API Server and Database, with no cache at all, already clears both the success-rate and latency bars. Look at what it costs.","The full set of trending tags is small enough to hold entirely in a modestly-sized cache. What happens to the database's own workload once that's true?"]$j$::jsonb,
  $j$["A cache absorbs the most benefit exactly when traffic is skewed toward a small set of hot keys — which real 'trending'/'popular' feeds almost always are.","Sizing a backend correctly clears the functional bars, but a budget can still rule it out — a cheaper shape that does less raw work isn't just cleverer, it's often required.","A cache sized to hold the entire hot set turns nearly every request into a hit, collapsing the database's real workload down to almost nothing."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A cache sized to hold every trending tag at once — so virtually every feed load is answered without touching the database — in front of a minimally-sized database.","editorial":["The traffic here is about as skewed as it gets: everyone loading the feed is asking for the same small set of trending tags. A properly-sized API Server and Database, with no cache at all, already handles that traffic just fine functionally — 100% success, comfortable latency. The problem is purely cost: doing real database work for the same repeated question, over and over, adds up.","A cache sized to hold the entire trending set turns almost every request into a hit. Once that's true, the database behind it barely needs to do anything — its own sizing (and its cost) collapses along with the volume actually reaching it.","A common near-miss: sizing the cache too small to hold the full set of trending tags. When even a few hot tags keep falling out of cache, a meaningful slice of traffic still hits the database on every request, and the savings mostly evaporate."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":300,"keyPoolSize":40}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":3,"maxQueueLength":30,"processingTimeMs":1}},{"id":"cache","type":"cache","label":"Cache","position":{"x":600,"y":200},"config":{"capacity":40,"evictionPolicy":"lru","ttlMs":0}},{"id":"db","type":"database","label":"Database","position":{"x":860,"y":200},"config":{"maxConnections":1,"maxQueueLength":20,"processingTimeMs":1}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"cache"},{"source":"cache","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$iot-sensor-ingestion$j$,
  1,
  'PUBLISHED',
  $j$IoT Sensor Ingestion$j$,
  2,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$A fleet of thousands of smart thermostats phones home every few seconds with a reading. Nobody's reading any single sensor's history over and over — this is almost pure write volume, not the kind of repeat-lookup traffic a cache is built for. Engineering's job is to make sure every reading actually gets written, on a budget that scales sanely with fleet size instead of linearly with however many connections the database happens to have.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":380,"keyPoolSize":800}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":380}$j$::jsonb,
  8000,
  920,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.97,"label":"At least 97% of sensor readings are written","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":150,"label":"95% of writes complete within 150ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  750,
  FALSE,
  $j$["This traffic is almost pure writes, spread across thousands of distinct sensors — nothing here is a good candidate for a cache. What else determines how much a database can absorb?","A properly-sized SQL database can clear both the success-rate and latency bars here. Check what it costs against the budget.","The Database entity has a `type` field. What does switching it actually change, and does it cost anything extra?"]$j$::jsonb,
  $j$["Not every high-volume workload is a caching problem — a cache only pays off when the same keys repeat, and pure write ingestion across a huge key space doesn't.","A database's `type` (SQL vs NoSQL) changes its effective connection ceiling and per-query time at no extra cost — picking the right one for a write-heavy workload can be the difference between clearing a budget and blowing it.","Two builds can both be functionally correct — the deciding factor is often which one the budget actually allows."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A NoSQL-type database, modestly sized — its connection-ceiling and query-time multiplier clears the same write volume a much larger SQL pool would need, at a fraction of the cost.","editorial":["This traffic doesn't repeat — thousands of sensors, each writing its own reading, means there's no hot key for a cache to exploit. A cache genuinely doesn't help here, unlike this catalogue's caching-focused scenarios.","A properly-sized SQL database clears the success-rate and latency bars just fine functionally. The problem is purely cost: reaching that same throughput ceiling with a SQL connection pool costs more than the budget allows.","Switching the Database's own `type` to NoSQL applies a real connection-ceiling and query-time multiplier — several times the effective throughput of the same pool size, at zero extra cost. A much smaller, cheaper NoSQL pool reaches the same ceiling a bigger SQL one needs.","A common near-miss: switching to NoSQL but leaving the pool sized as if it still needed SQL-level capacity. The whole point of the multiplier is that a smaller pool now does the same job — leaving it oversized just pays for headroom nothing here needs."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":380,"keyPoolSize":800}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"maxConcurrent":4,"maxQueueLength":50,"processingTimeMs":1}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"type":"nosql","maxConnections":3,"maxQueueLength":50,"processingTimeMs":1}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$concert-ticket-drop$j$,
  1,
  'PUBLISHED',
  $j$Concert Ticket Drop Confirmations$j$,
  2,
  $j$["message-queues"]$j$::jsonb,
  NULL,
  $j$A ticketing platform opens sales for a popular concert at a fixed time — everyone hits 'buy' within the same few hundred milliseconds of doors opening, then it's quiet until the next drop. Every purchase needs a confirmation, and losing one under load means a fan who paid but never got their ticket. Engineering's job is to make every drop feel instant to the buyer, without paying to keep the backend permanently sized for a spike that lasts a fraction of a second.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":70}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"burst","rate":350,"duration":250,"interval":5000}$j$::jsonb,
  15000,
  930,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.97,"label":"At least 97% of purchases are confirmed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":200,"label":"95% of confirmations arrive within 200ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  450,
  FALSE,
  $j$["Ticket buyers don't trickle in — watch the packet animation on a run. What happens to a synchronous Database's own backlog the instant hundreds of purchases land at once?","A Database's own backlog can absorb a burst for free — it isn't billed. So why would inserting a Message Queue ever be worth it?","The buyer is still waiting the whole time their request sits in a Database's backlog. Is there a component that can confirm the purchase before the actual write has happened?","Once a Message Queue is durably holding a burst, how big does the Database behind it actually need to be — sized for the drop's peak, or for the average rate across drops?"]$j$::jsonb,
  $j$["A synchronous backend can absorb a burst it can't otherwise handle just by raising its own backlog — but every request in that backlog makes the buyer wait, so latency (not capacity) is what actually fails.","A Message Queue confirms a request the instant it's durably admitted, decoupling the buyer's wait from how long the actual downstream write takes.","Once a queue is absorbing bursts, the backend behind it only needs to be sized for the sustained average rate across drops, not the instantaneous peak of any one of them."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A Message Queue between the API Server and Database, confirming every purchase the instant it's durably queued — with the Database itself sized for the average rate across drops, not any single drop's peak.","editorial":["A Database's own backlog can absorb a 350-purchase burst for free — it isn't billed at all. An unconfigured build doesn't fail because the burst is too big; it fails because a default Database's small backlog is too small to hold it, and once it's full, the overflow is rejected outright.","Raising the Database's own backlog large enough to admit the whole burst directly does fix that — every purchase gets in. But the buyer is still waiting synchronously the whole time their confirmation sits in that backlog behind everyone ahead of them, so the tail of every drop pushes latency well past what a buyer would tolerate.","Brute-force sizing the Database's own connection count high enough to drain the burst almost instantly does fix the latency too — but connections (unlike backlog depth) are billed, and provisioning enough of them to make a synchronous burst feel instant costs far more than the traffic's own average rate would ever justify.","A Message Queue confirms the buyer the instant their purchase is durably queued, regardless of how long the eventual database write takes. The Database behind the queue only ever needs to keep up with the sustained average rate — a smaller, cheaper Database, at near-zero extra cost for the queue itself."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":70}},{"id":"api","type":"api","label":"API Server","position":{"x":320,"y":200},"config":{"maxConcurrent":10,"maxQueueLength":200,"processingTimeMs":1}},{"id":"mq","type":"message_queue","label":"Message Queue","position":{"x":560,"y":200},"config":{"consumerCount":8,"maxQueueLength":300,"dispatchTimeMs":1}},{"id":"db","type":"database","label":"Database","position":{"x":800,"y":200},"config":{"maxConnections":2,"maxQueueLength":50,"processingTimeMs":1}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"mq"},{"source":"mq","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$price-alert-notifications$j$,
  1,
  'PUBLISHED',
  $j$Price Alert Notifications$j$,
  2,
  $j$["message-queues"]$j$::jsonb,
  NULL,
  $j$A stock-trading app lets users set a price alert on any ticker. Alerts don't trickle in steadily — the instant a watched price actually crosses its threshold, every user watching that ticker needs a notification at once, in a tight burst. Between triggers, the system is quiet. Engineering's job is to make sure a burst of alerts never gets lost or makes anyone wait, without paying to keep the backend permanently sized for a spike that only happens for a fraction of a second at a time.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":67}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"burst","rate":400,"duration":200,"interval":6000}$j$::jsonb,
  18000,
  700,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.97,"label":"At least 97% of alerts are delivered","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":250,"label":"95% of alerts are acknowledged within 250ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  500,
  FALSE,
  $j$["Alerts don't arrive at a steady rate — watch the packet animation on a run. What actually happens to a synchronous Database's own backlog the instant several hundred requests land at once?","A Database's own backlog (Max Queue Length) can absorb a burst for free — it's not billed. So why would inserting a Message Queue ever be worth it?","The client is still waiting the whole time a request sits in a Database's backlog. Is there a component that can tell the client 'received' before the actual write has happened?","Once a Message Queue is durably holding a burst, how big does the Database behind it actually need to be — sized for the peak, or for the average?"]$j$::jsonb,
  $j$["A synchronous backend can absorb a burst it can't otherwise handle just by raising its own backlog — but every request in that backlog makes the client wait, so latency (not capacity) is what actually fails.","A Message Queue acknowledges a request the instant it's durably admitted, decoupling the client's wait from how long the actual downstream processing takes.","Once a queue is absorbing bursts, the backend behind it only needs to be sized for the sustained average rate, not the instantaneous peak — a real, meaningful cost saving over brute-force sizing."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A Message Queue between the API Server and Database, acknowledging every alert the instant it's durably queued — with the Database itself sized for the average rate, not the burst's peak.","editorial":["The Database's own backlog (Max Queue Length) can absorb a 400-request burst for free — it isn't billed at all. So an unconfigured build doesn't fail on capacity in the usual sense; a default Database's small backlog (105 total admission capacity) is simply too small to hold the burst, and once it's full, the overflow is rejected outright.","Raising the Database's own backlog large enough to admit the whole burst directly does fix that — every alert gets in. But the client is still waiting synchronously the whole time its request sits in that backlog behind everyone ahead of it, so the tail of every burst pushes p95 latency well past what a real client would tolerate.","Brute-force sizing the Database's own connection count high enough to drain the burst almost instantly does fix the latency too — but connections (unlike backlog depth) are billed, and provisioning enough of them to make a synchronous burst feel instant costs meaningfully more than the traffic's own average rate would ever justify.","A Message Queue sidesteps the tradeoff entirely: it acknowledges the client the instant a message is durably queued, regardless of how long the eventual database write takes. The Database behind the queue only ever needs to keep up with the *sustained average* rate (drain the backlog before the next burst piles more on), not the instantaneous peak — a smaller, cheaper Database, at near-zero extra cost for the queue itself.","A common near-miss: adding a Message Queue but then leaving everything else generously (or maximally) sized anyway. The queue's value is specifically that it lets the rest of the architecture shrink — a queue in front of an oversized API Server and Database still clears the metric constraints, it just doesn't clear the budget."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":67}},{"id":"api","type":"api","label":"API Server","position":{"x":320,"y":200},"config":{"maxConcurrent":10,"maxQueueLength":200,"processingTimeMs":1}},{"id":"mq","type":"message_queue","label":"Message Queue","position":{"x":560,"y":200},"config":{"consumerCount":10,"maxQueueLength":300,"dispatchTimeMs":1}},{"id":"db","type":"database","label":"Database","position":{"x":800,"y":200},"config":{"maxConnections":2,"maxQueueLength":50,"processingTimeMs":1}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"mq"},{"source":"mq","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$weather-forecast-api$j$,
  1,
  'PUBLISHED',
  $j$Weather Forecast API$j$,
  2,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$A weather app's forecast endpoint gets checked constantly — commuters, farmers, event planners, all pulling the latest numbers throughout the day. There's no clever shortcut here, no obviously hot key to cache, no burst pattern to smooth out — just a steady stream of requests that needs to be served correctly, calculated for the actual traffic, not guessed at.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":380}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":380}$j$::jsonb,
  10000,
  1000,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of forecast requests succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":100,"label":"95% of requests complete within 100ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  850,
  FALSE,
  $j$["The Client's request rate is fixed at 380 req/s. What's a default API Server and Database's own raw throughput ceiling, at their default settings?","Most requests eventually succeed even when the ceiling is too low — so if success rate looks acceptable, what's actually failing?","Is there a cheaper way to hit the same latency bar than just cranking every dial as high as it'll go?"]$j$::jsonb,
  $j$["A connection pool's throughput ceiling is connections × (1000 / processing time) — a number you calculate, not one that takes care of itself at default settings.","Success rate alone doesn't tell the whole story — a backend can eventually process almost everything and still fail a real latency bar under queueing delay.","Budget makes 'just add more capacity' a real tradeoff — the same latency bar is reachable at wildly different costs."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A deliberately, modestly sized API Server and Database — no cache, no special database type, no queue. Just enough capacity to clear the latency bar, no more.","editorial":["This traffic doesn't have a hidden trick — no hot key, no burst, nothing to exploit. It's the most basic version of the lesson every other scenario in this catalogue builds on: calculate the ceiling correctly.","A default API Server and Database's raw throughput ceiling sits right at the edge of what 380 req/s demands, so even though most requests eventually get a response, the queueing delay is enough to blow a real latency bar.","Fixing it doesn't require anything exotic — raising the Database's connection count and the API Server's own concurrency a modest amount clears both the success-rate and latency constraints comfortably, well within budget."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":380}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"maxConcurrent":8,"maxQueueLength":50,"processingTimeMs":2}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"maxConnections":8,"maxQueueLength":50,"processingTimeMs":5}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$warehouse-inventory-sync$j$,
  1,
  'PUBLISHED',
  $j$Warehouse Inventory Sync$j$,
  2,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$A logistics company's warehouse-floor app is lagging — every scan of a shelf barcode checks and updates inventory counts, and the dashboard shows both the API layer and the database running hot. It's tempting to just scale up whichever one looks busier. Engineering's job is to find out which tier is actually the ceiling before spending any budget on either.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":400,"keyPoolSize":600}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":400}$j$::jsonb,
  10000,
  1010,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of scans sync successfully","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":250,"label":"95% of syncs complete within 250ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  850,
  FALSE,
  $j$["Both the API Server and the Database show high utilization in an unconfigured build. Are they necessarily two independent problems?","Try raising only the API Server's own concurrency, leaving the Database untouched. Does that actually move success rate?","Now try the opposite: raise only the Database, leave the API Server at its default. Compare."]$j$::jsonb,
  $j$["A saturated-looking component can just be waiting on the real bottleneck downstream — utilization tells you something is busy, not why.","Verify a fix actually helps before spending budget on it — raising the wrong tier's capacity can cost more while barely moving the outcome.","Once the real ceiling is identified, fixing just that one component is often enough."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"The API Server left near its default — the Database, deliberately sized to actually clear the traffic, was always the real ceiling.","editorial":["An unconfigured build shows both the API Server and the Database at high utilization — the natural instinct is to treat that as two separate shortages. It isn't: the API Server's own concurrent slots are occupied waiting on a struggling Database response.","The tell is what happens when you raise only the API Server's concurrency: success rate barely moves, and the build costs more for almost the same result.","Raising only the Database fixes the whole picture at once. Utilization is a symptom, not a diagnosis; verify a fix actually helps before spending budget chasing the component that merely looks busy."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":400,"keyPoolSize":600}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"maxConcurrent":5,"maxQueueLength":30,"processingTimeMs":2}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"maxConnections":7,"maxQueueLength":40,"processingTimeMs":5}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$ad-auction-bidding$j$,
  1,
  'PUBLISHED',
  $j$Ad Auction Bidding Events$j$,
  3,
  $j$["message-queues"]$j$::jsonb,
  NULL,
  $j$A real-time ad exchange runs an auction round every few seconds — every connected bidder fires a bid in the same brief window, then goes quiet until the next round. Every accepted bid needs to be durably recorded; losing one under load means an advertiser paid for an impression they didn't actually win. Engineering's job is to make sure every round's flood of bids lands cleanly, without paying to keep the backend permanently sized for a spike that only lasts a fraction of a second.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":80}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"burst","rate":400,"duration":250,"interval":5000}$j$::jsonb,
  15000,
  960,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.97,"label":"At least 97% of bids are recorded","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":25,"label":"95% of bids are acknowledged within 25ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  450,
  FALSE,
  $j$["Bids don't trickle in — every connected bidder fires within the same brief window, every round. What happens to a synchronous Database's own backlog the instant hundreds of bids land at once?","A Database's own backlog can absorb a burst for free — it isn't billed. So why would inserting a Message Queue ever be worth it?","The bidder is still waiting the whole time their bid sits in a Database's backlog. Is there a component that can confirm the bid before the actual write has happened?"]$j$::jsonb,
  $j$["A synchronous backend can absorb a burst it can't otherwise handle just by raising its own backlog — but every request in that backlog makes the caller wait, so latency (not capacity) is what actually fails.","A Message Queue confirms a request the instant it's durably admitted, decoupling the caller's wait from how long the actual downstream write takes.","Once a queue is absorbing bursts, the backend behind it only needs to be sized for the sustained average rate across rounds, not any single round's peak."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A Message Queue between the API Server and Database, confirming every bid the instant it's durably queued — with the Database itself sized for the average rate across rounds, not any single round's peak.","editorial":["A Database's own backlog can absorb a 400-bid burst for free. An unconfigured build fails because a default Database's small backlog is too small to hold it, not because the burst itself is unmanageable.","Brute-force sizing the Database's own connection count high enough to drain the burst almost instantly does clear the metrics — but connections are billed, and provisioning enough of them to make a synchronous burst feel instant costs far more than the traffic's own average rate would ever justify.","A Message Queue confirms the bidder the instant their bid is durably queued, regardless of how long the eventual database write takes. The Database behind the queue only ever needs to keep up with the sustained average rate across rounds — a smaller, cheaper Database, at near-zero extra cost for the queue itself."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":80}},{"id":"api","type":"api","label":"API Server","position":{"x":320,"y":200},"config":{"maxConcurrent":10,"maxQueueLength":200,"processingTimeMs":1}},{"id":"mq","type":"message_queue","label":"Message Queue","position":{"x":560,"y":200},"config":{"consumerCount":8,"maxQueueLength":300,"dispatchTimeMs":1}},{"id":"db","type":"database","label":"Database","position":{"x":800,"y":200},"config":{"maxConnections":15,"maxQueueLength":50,"processingTimeMs":20}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"mq"},{"source":"mq","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$slow-search-endpoint$j$,
  1,
  'PUBLISHED',
  $j$Slow Search Endpoint$j$,
  3,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$Product search has gotten noticeably slower, and both the API layer and the database look completely maxed out in the monitoring dashboard. The obvious instinct is to scale up whatever looks busiest — but scaling the wrong tier just means paying more for the same slow search. Engineering's job is to find out which one is actually the ceiling before spending any budget on either.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":420,"keyPoolSize":1000}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":420}$j$::jsonb,
  10000,
  940,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of searches succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":200,"label":"95% of searches complete within 200ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  800,
  FALSE,
  $j$["Both the API Server and the Database show high utilization in an unconfigured build. Are they necessarily two independent problems?","Try raising only the API Server's own concurrency, leaving the Database untouched. Does that actually move success rate — and if not, what does that tell you?","Now try the opposite: raise only the Database, leave the API Server at its default. Compare."]$j$::jsonb,
  $j$["A saturated-looking component can just be waiting on the real bottleneck downstream — utilization tells you something is busy, not why.","Verify a fix actually helps before spending budget on it — raising the wrong tier's capacity can cost more while barely moving the outcome.","Once the real ceiling is identified, fixing just that one component (not both) is often enough."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"The API Server left near its default — the Database, deliberately sized to actually clear the traffic, was always the real ceiling.","editorial":["An unconfigured build shows both the API Server and the Database at 100% utilization — the natural instinct is to treat that as two separate shortages. It isn't: the API Server's own concurrent slots are occupied waiting on a struggling Database response, not short on their own raw capacity.","The tell is what happens when you raise only the API Server's concurrency: success rate barely moves, and the build costs more for almost the same result. The API was never the ceiling — it was just as backed up as everything behind it.","Raising only the Database fixes the whole picture at once — both the Database's own utilization and the API Server's, since the API Server was only ever waiting on it. Utilization is a symptom, not a diagnosis; verify a fix actually helps before spending budget chasing the component that merely looks busy."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":420,"keyPoolSize":1000}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"maxConcurrent":5,"maxQueueLength":30,"processingTimeMs":2}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"maxConnections":8,"maxQueueLength":40,"processingTimeMs":5}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$checkout-timeout-mystery$j$,
  1,
  'PUBLISHED',
  $j$Checkout Timeout Mystery$j$,
  3,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$Checkout has been timing out under load, and just like last time the search endpoint was slow, both the API layer and the database look maxed out. It's tempting to assume the same fix applies — but checkout runs real, unavoidable business logic on every request (fraud checks, tax calculation) that no database tuning can shortcut. Engineering's job is to actually verify which tier is the real ceiling this time, not assume it's the same one as before.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":350}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"processingTimeMs":20,"maxConcurrent":3}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":350}$j$::jsonb,
  10000,
  970,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of checkouts succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":200,"label":"95% of checkouts complete within 200ms","unit":"ms"}]$j$::jsonb,
  $j$["client","api"]$j$::jsonb,
  $j${"client":["requestRate"],"api":["processingTimeMs"]}$j$::jsonb,
  800,
  FALSE,
  $j$["The API Server's own per-request processing time is fixed here — it isn't a lever you can turn. What lever does the API Server actually have left?","Try raising only the database's capacity, leaving the API Server's concurrency untouched. Does that meaningfully move success rate?","Now try raising only the API Server's own concurrency instead. Compare — and check whether success alone is enough, or whether latency still needs more headroom."]$j$::jsonb,
  $j$["A fixed per-request processing cost is a real, unavoidable ceiling — no amount of downstream tuning removes it, only enough concurrency to run more of that work in parallel does.","The same symptom (two tiers both at high utilization) can have a completely different real cause each time — diagnose fresh, don't pattern-match from the last problem.","Clearing success rate alone doesn't mean you're done — the same fix often needs a bit more headroom before latency clears too."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"The API Server's concurrency raised enough to run its fixed per-request work in genuine parallel, with the database sized modestly — it was never the real ceiling.","editorial":["This time, adding a Database without touching the API Server's own concurrency doesn't just fail to help — it makes success rate worse. Every request now has a response leg to route back through the API Server too, and that server's concurrency was already the real ceiling — doubling the work routed through the same small pool bites harder, not less.","Raising the API Server's own concurrency helps a lot on success rate, but a small bump isn't quite enough to also clear the latency bar — there's a difference between 'enough capacity to eventually get through' and 'enough headroom that nothing queues for long.'","Pushing the API Server's concurrency further, while leaving the database only modestly sized (it was never the bottleneck), clears both bars at once. The lesson from the other diagnose-the-bottleneck scenarios still applies — verify before you spend — it just points the other direction this time."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":350}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"processingTimeMs":20,"maxConcurrent":22,"maxQueueLength":60}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"maxConnections":6,"maxQueueLength":40,"processingTimeMs":3}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$public-transit-tracker-api$j$,
  1,
  'PUBLISHED',
  $j$Public Transit Tracker API$j$,
  3,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$A city's public transit app shows real-time bus and train positions — commuters checking constantly whether their ride is on time, all day, every day. There's no obviously hot key to cache, no burst pattern to smooth out, no write-heavy volume that favors a different database type — just a steady stream of requests that needs to be served correctly, calculated for the actual traffic, not guessed at.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":430}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":430}$j$::jsonb,
  10000,
  1110,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.97,"label":"At least 97% of position checks succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":70,"label":"95% of checks complete within 70ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  900,
  FALSE,
  $j$["The Client's request rate is fixed at 430 req/s. What's a default API Server and Database's own raw throughput ceiling, at their default settings?","Most requests eventually succeed even when the ceiling is too low — so if success rate looks acceptable, what's actually failing?","Is there a cheaper way to hit the same latency bar than just cranking every dial as high as it'll go?"]$j$::jsonb,
  $j$["A connection pool's throughput ceiling is connections × (1000 / processing time) — a number you calculate, not one that takes care of itself at default settings.","Success rate alone doesn't tell the whole story — a backend can eventually process almost everything and still fail a real latency bar under queueing delay.","Budget makes 'just add more capacity' a real tradeoff — the same latency bar is reachable at wildly different costs."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A deliberately, modestly sized API Server and Database — no cache, no special database type, no queue. Just enough capacity to clear the latency bar, no more.","editorial":["This traffic doesn't have a hidden trick — no hot key, no burst, no write-heavy volume. It's the most basic version of the lesson every other scenario in this catalogue builds on: calculate the ceiling correctly.","A default API Server and Database's raw throughput ceiling sits right at the edge of what 430 req/s demands, so even though most requests eventually get a response, the queueing delay is enough to blow a real latency bar.","Fixing it doesn't require anything exotic — raising the Database's connection count and the API Server's own concurrency a modest amount clears both constraints comfortably, well within budget."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":430}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"maxConcurrent":6,"maxQueueLength":50,"processingTimeMs":2}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"maxConnections":7,"maxQueueLength":50,"processingTimeMs":4}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$flash-sale$j$,
  1,
  'PUBLISHED',
  $j$Flash Sale$j$,
  3,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$A marketplace is running a site-wide flash sale — thousands of different items across the entire catalog are discounted at once, not just one hero product. Checkout requests are landing on a huge, diverse spread of distinct orders, so there's no small set of repeat lookups to lean on. Engineering's job is to design a checkout service that keeps up with the write volume, on a budget that survives the sale ending.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":400,"keyPoolSize":1000}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":400}$j$::jsonb,
  8000,
  300,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of checkout requests succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":250,"label":"95% of requests complete within 250ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  1600,
  FALSE,
  $j$["Drop an unconfigured API Server and Database on the canvas and wire them up. Which one is maxed out — and what's a default Database's own raw ceiling (connections x 1000/query time) against 400 req/s?","You can raise the Database's Max Connections to fix that ceiling — but check the Cost panel as you do. What does that cost by the time it clears 400 req/s?","Open the Database's Inspector panel and look at the Type field. What does switching it actually change about the connection ceiling and query time — and does that fit a workload that's mostly high-volume writes across a huge, diverse set of orders?","With Key Pool Size fixed this large, would a Cache in front of the database actually see many repeat lookups?"]$j$::jsonb,
  $j$["A connection pool's throughput ceiling (connections x 1000/query time) is a number you design for — an unconfigured default database falls short of real traffic before you've made a single decision.","Database type is a real architectural choice, not just a config value: trading SQL's joins/consistency for NoSQL's much higher connection-ceiling and faster per-query time can multiply effective capacity at the *same* dollar cost, for the right access pattern.","Brute-force overprovisioning (cranking a SQL pool sky-high) still clears functional constraints, but the budget catches what raw capacity numbers don't — picking the right tool beats buying more of the wrong one."]$j$::jsonb,
  $j${"prompt":"The Client sends a fixed 400 req/s for the whole run, spread across 1000 distinct orders (not a small repeatable set). A default, unconfigured Database (5 connections, 15ms per query) has a raw ceiling of connections x (1000/query time). Does that clear 400 req/s?","worked":"5 connections x (1000/15ms) = 333 req/s — already short of the 400 req/s arriving, on average, before a single burst is considered. An unconfigured Database isn't a neutral starting point here; it's already undersized. Raising Max Connections closes that gap, but check what it costs as you go — a connection pool's cost tier climbs in fixed steps (every 20 connections), and a plain SQL pool sized for real headroom at this volume adds up fast. The Database's own Type field is worth a look before reaching for more SQL connections."}$j$::jsonb,
  $j${"template":"This run landed at {{successRate}} success, {{throughput}} completed, and a p95 latency of {{p95Latency}} — but those numbers alone don't say whether you solved this well or just expensively. Check the Budget row and star rating above: the same success rate is reachable anywhere from a modestly-priced, right-sized database to well over a thousand dollars a month just by buying more SQL connections. The database's Type field — SQL vs. NoSQL — is usually the real lever here, not fine connection-count tuning."}$j$::jsonb,
  $j${"summary":"A NoSQL-type database, minimally sized — its connection-ceiling and query-time multiplier does more with a tiny pool than buying a much larger SQL one ever could, at the same cost.","editorial":["There's no cache in the intended solution here — checkout writes aren't cacheable, so unlike this catalogue's caching-focused scenarios, the lever isn't cutting the volume of requests reaching the database.","The real lever is the Database's own `type` field: switching it from SQL to NoSQL applies a real connection-ceiling and query-time multiplier — several times the effective throughput of the same pool size, at no extra cost. Sizing a SQL pool large enough to match that throughput costs meaningfully more for the same result.","A properly-sized SQL build already passes (2 stars) — the database type switch is what pushes it further (3 stars) for a lower monthly cost, not a different shape of architecture, just a better-chosen technology underneath the same one.","This scenario locks the Client's key pool size specifically because, at the schema's smaller default pool, a Cache would trivialize the problem — the traffic's own shape is part of what makes the database-type lesson the one worth learning here, not an arbitrary restriction."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":400,"keyPoolSize":1000}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":5,"maxQueueLength":20,"processingTimeMs":1}},{"id":"database","type":"database","label":"Database","position":{"x":600,"y":200},"config":{"type":"nosql","maxConnections":3,"maxQueueLength":40,"processingTimeMs":1,"failureProbability":0}}],"connections":[{"source":"client","target":"api","latencyMs":5},{"source":"api","target":"database","latencyMs":5}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$parking-reservation-platform$j$,
  1,
  'PUBLISHED',
  $j$Parking Reservation Platform$j$,
  3,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$A citywide parking reservation platform grew from a single weekend side project into eight backend services — accounts, search, checkout, reservation history, payments, notifications, live spot inventory, and garage reviews — all still funneled through one shared API tier and one shared database from day one. The moment reservations spike, the whole platform slows down together, and it looks like everything is struggling at once. Engineering's job is to actually figure out what's struggling — and what's just waiting on what — before spending a cent fixing the wrong thing.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":400,"keyPoolSize":1000,"routePoolSize":8}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":400}$j$::jsonb,
  10000,
  500,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of requests across all 8 services succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":150,"label":"95% of requests complete within 150ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  2000,
  FALSE,
  $j$["Drop an unconfigured API Server and Database on the canvas, wire them up, and run it. Check the Inspector — is only one of them near 100% utilization, or both?","If two entities both look saturated at once, that doesn't necessarily mean two independent problems. Try raising just the API server's Max Concurrent and re-running — does it actually move the success rate?","A default Database's raw ceiling is connections x (1000/query time). Does it clear 400 req/s on paper — and if it doesn't, would a faster API server change that ceiling at all?","Once you've found the lever that actually moves the number, tightening Processing Time (not just adding more connections) is what pushes latency down further from there."]$j$::jsonb,
  $j$["High utilization on two entities at once doesn't always mean two independent bottlenecks — a component waiting on a struggling downstream neighbor looks just as saturated as the neighbor itself.","Verify a fix actually moves the number before spending more budget on it — raising the wrong lever can leave you exactly as broken, just more expensive.","Once the real bottleneck is sized correctly, processing time (not just connection/concurrency count) is what separates an adequate build from a well-optimized one on latency."]$j$::jsonb,
  $j${"prompt":"The Client sends a fixed 400 req/s. A default, unconfigured Database (5 connections, 15ms per query) has a raw ceiling of connections x (1000/query time). Does that clear 400 req/s — and if the API server ALSO shows ~100% utilization in that same run, does raising the API server's own concurrency create any more room at the database?","worked":"5 connections x (1000/15ms) = 333 req/s — short of the 400 req/s arriving. The database is the real ceiling. The API server's own near-100% utilization in that run isn't a second, independent shortage — every request is held in an API server slot for the whole time it waits on the database, so a struggling database makes the API server look just as saturated as it is, purely from backpressure. Raising the API server's own concurrency doesn't create any more room downstream; only sizing the database actually does."}$j$::jsonb,
  $j${"template":"This run landed at {{successRate}} success and a p95 latency of {{p95Latency}} — but those numbers alone don't say whether you found the real bottleneck or just spent budget on the one that looked worst. Check the Budget row and star rating above: a build that sizes the database correctly (even leaving the API server at its default) clears every gate; a build that raises the API server's concurrency without touching the database doesn't, no matter how high. Once the real lever is found, tightening processing time (not just adding more connections) is what separates a merely-adequate build from a well-optimized one."}$j$::jsonb,
  $j${"summary":"A single, correctly-sized API Server and Database — concurrency and connections right-sized for the real 400 req/s ceiling, processing time tightened to reduce latency further. No second pool: splitting this traffic never actually pays for itself under a real budget.","editorial":["An unconfigured build shows both the API Server and Database at roughly 100% utilization — but that's two symptoms of one problem, not two independent shortages. The API Server's slots are stuck waiting on a struggling downstream database (backpressure), not short on their own raw capacity.","The tell: raising the API Server's own concurrency alone (even 3x higher) barely moves success rate at all, because the database was always the true ceiling. Sizing the database alone — leaving the API Server at its default — fixes both symptoms at once. Utilization is a symptom, not a diagnosis; verify a fix actually helps before spending budget chasing the wrong bottleneck.","A tempting-looking fix that does NOT work here: carving the busiest route onto its own dedicated API+Database pair behind a Reverse Proxy. Splitting one pool into two never reduces base cost (this app's pricing tiers are subadditive — two smaller pools always cost at least as much as one pool sized for the same total capacity) and loses pooling efficiency besides, so it comes out strictly worse on both cost and latency versus one properly-sized pool.","Both the traffic rate and key pool size are locked here for the same reason as Flash Sale's: at a smaller pool, a Cache would trivialize this scenario and the utilization-diagnosis lesson would never get tested."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":400,"keyPoolSize":1000,"routePoolSize":8}},{"id":"api","type":"api","label":"API Server","position":{"x":360,"y":200},"config":{"maxConcurrent":5,"maxQueueLength":20,"processingTimeMs":1}},{"id":"database","type":"database","label":"Database","position":{"x":640,"y":200},"config":{"maxConnections":11,"maxQueueLength":30,"processingTimeMs":1,"failureProbability":0}}],"connections":[{"source":"client","target":"api","latencyMs":5},{"source":"api","target":"database","latencyMs":5}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$live-sports-scoreboard$j$,
  1,
  'PUBLISHED',
  $j$Live Sports Scoreboard$j$,
  3,
  $j$["caching"]$j$::jsonb,
  NULL,
  $j$During a major tournament, everyone's refreshing the same handful of live scoreboards at once — a huge crowd, an incredibly narrow set of things they're actually looking at. Every refresh that reaches the database for a score that hasn't even changed since the last refresh is money spent for nothing. Engineering's job is to keep the board feeling live for a crowd this size, without paying database rates for traffic that's really just re-asking the same handful of questions.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":420,"keyPoolSize":50}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":420}$j$::jsonb,
  8000,
  1020,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.97,"label":"At least 97% of scoreboard refreshes succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":60,"label":"95% of refreshes complete within 60ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  550,
  FALSE,
  $j$["Everyone watching is refreshing one of a small handful of live scoreboards. What does that mean for how often the database actually needs to be asked?","A properly-sized API Server and Database, with no cache at all, already clears both the success-rate and latency bars. Check what it costs.","The full set of active scoreboards is small enough to hold entirely in a modestly-sized cache."]$j$::jsonb,
  $j$["At high enough volume, even a functionally correct, properly-sized build can be wildly over budget — sizing alone doesn't fix a cost problem caused by repeat work.","A cache absorbs the most benefit exactly when traffic is skewed toward a small set of hot keys, which a live scoreboard during a big event is about as skewed as it gets.","A cache sized to hold the entire hot set turns nearly every request into a hit, collapsing the database's real workload — and its cost — down to almost nothing."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A cache sized to hold every active scoreboard at once — so virtually every refresh is answered without touching the database — in front of a minimally-sized database.","editorial":["A properly-sized API Server and Database, with no cache at all, handles this traffic just fine functionally. The problem is purely cost, and at this volume it isn't subtle — a capacity-adequate build here costs well over the budget, not just a little over it.","A cache sized to hold every active scoreboard turns almost every refresh into a hit. Once that's true, the database behind it barely needs to do anything — its own sizing (and its cost) collapses along with the volume actually reaching it.","This is a case where sizing alone genuinely cannot solve the problem within budget — the cache isn't just the cheaper option here, it's the only one that fits."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":420,"keyPoolSize":50}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":5,"maxQueueLength":40,"processingTimeMs":2}},{"id":"cache","type":"cache","label":"Cache","position":{"x":600,"y":200},"config":{"capacity":50,"evictionPolicy":"lru","ttlMs":0}},{"id":"db","type":"database","label":"Database","position":{"x":860,"y":200},"config":{"maxConnections":2,"maxQueueLength":30,"processingTimeMs":4}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"cache"},{"source":"cache","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$ride-hailing-location-pings$j$,
  1,
  'PUBLISHED',
  $j$Ride-Hailing Location Pings$j$,
  3,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$Every active driver's app phones home with a GPS ping every couple of seconds — pure write volume, spread across thousands of independent drivers, with nothing here that repeats often enough for a cache to help. Engineering's job is to make sure every ping actually lands, on a budget that scales sanely with fleet size instead of linearly with however many connections the database happens to have.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":430,"keyPoolSize":1000}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":430}$j$::jsonb,
  8000,
  1030,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.97,"label":"At least 97% of location pings are written","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":100,"label":"95% of writes complete within 100ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  780,
  FALSE,
  $j$["Thousands of independent drivers, each pinging their own location — nothing here is a good candidate for a cache. What else determines how much a database can absorb?","A properly-sized SQL database can clear both the success-rate and latency bars here. Check what it costs against the budget.","The Database entity has a `type` field. What does switching it actually change, and does it cost anything extra?"]$j$::jsonb,
  $j$["Not every high-volume workload is a caching problem — pure write traffic across a huge key space gives a cache nothing to exploit.","A database's `type` (SQL vs NoSQL) changes its effective connection ceiling and per-query time at no extra cost — picking the right one can be the difference between clearing a budget and blowing it.","Two builds can both be functionally correct — the deciding factor is often which one the budget actually allows."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A NoSQL-type database, tightly sized — its connection-ceiling and query-time multiplier clears the same write volume a much larger SQL pool would need, at a fraction of the cost.","editorial":["This traffic doesn't repeat — thousands of drivers, each writing their own location, means there's no hot key for a cache to exploit.","A properly-sized SQL database clears the success-rate and latency bars just fine functionally. The problem is purely cost: reaching that same throughput ceiling with a SQL connection pool costs more than the budget allows.","Switching the Database's own `type` to NoSQL applies a real connection-ceiling and query-time multiplier — several times the effective throughput of the same pool size, at zero extra cost. A much smaller, cheaper NoSQL pool reaches the same ceiling a bigger SQL one needs."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":430,"keyPoolSize":1000}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"maxConcurrent":4,"maxQueueLength":50,"processingTimeMs":1}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"type":"nosql","maxConnections":3,"maxQueueLength":50,"processingTimeMs":1}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$viral-video-comments$j$,
  1,
  'PUBLISHED',
  $j$Viral Video Comments$j$,
  4,
  $j$["caching","system-design"]$j$::jsonb,
  NULL,
  $j$A video just went viral, and its comment thread is getting hammered — mostly the same few hundred comments, reloaded by everyone watching the video refresh the page. The comments API has always run on a database engine that's a little slow per-query, and under this kind of load that slowness is now the whole story: even a well-provisioned connection pool can't out-buy a query that's simply too slow, one at a time. Engineering's job is to make the thread feel fast for everyone piling on, on a budget that doesn't assume infinite headroom.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":200,"keyPoolSize":300}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":200}$j$::jsonb,
  8000,
  950,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.97,"label":"At least 97% of comment loads succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":46,"label":"95% of comment loads complete within 46ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  480,
  FALSE,
  $j$["Most people reloading the thread are seeing the same handful of comments. What does that suggest about how often the database actually needs to be asked?","Try giving the Database as many connections as it could reasonably want, with no cache at all. Does that alone bring latency under the bar?","A Database's own processing time per query doesn't shrink just because it has more connections — connections only help with how many queries run at once, not how long any single one takes. Is there a lever that changes the per-query time itself?"]$j$::jsonb,
  $j$["A database's own per-query processing time is a floor that raw connection count can't buy down — it's a separate lever from capacity.","A cache and a database-type choice solve different problems — one cuts how often the database gets asked at all, the other changes how long each ask takes. A workload can need both at once.","Not every requirement in a scenario is a cost constraint — a structural latency floor can rule out an option regardless of budget."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A cache absorbing most repeat lookups, in front of a NoSQL-type database — its lower per-query time is what actually clears the latency bar, no amount of SQL connections can buy that down.","editorial":["A cache alone gets most of the way there: it cuts how often the database gets asked at all, which is what a purely capacity- or cost-focused fix would chase. But even a generously-connected SQL database, fronted by a cache, still misses the latency bar — adding connections relieves queueing, it doesn't change how long any single query takes.","Switching the Database's own `type` to NoSQL applies a real per-query processing-time multiplier — the same underlying query now takes meaningfully less time, independent of how many connections are configured. That's what actually closes the latency gap SQL structurally can't.","This scenario needs both levers at once, and the margins are genuinely tight — this isn't a scenario with a comfortable buffer to spare, and that's honest: requiring two things to be right simultaneously costs more headroom than requiring just one."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":200,"keyPoolSize":300}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":6,"maxQueueLength":50,"processingTimeMs":1}},{"id":"cache","type":"cache","label":"Cache","position":{"x":600,"y":200},"config":{"capacity":100,"evictionPolicy":"lru","ttlMs":0}},{"id":"db","type":"database","label":"Database","position":{"x":860,"y":200},"config":{"type":"nosql","maxConnections":2,"maxQueueLength":40,"processingTimeMs":20}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"cache"},{"source":"cache","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$flight-status-push-updates$j$,
  1,
  'PUBLISHED',
  $j$Flight Status Push Updates$j$,
  4,
  $j$["message-queues"]$j$::jsonb,
  NULL,
  $j$When a flight's status changes — gate assignment, delay, boarding — every passenger tracking that flight needs a push notification at once, and a single popular route can have hundreds of people watching it. Between status changes, the system is quiet. A passenger who doesn't get notified in time can miss their gate change. Engineering's job is to make every update land fast for a crowd this size, without paying to keep the backend permanently sized for a spike that lasts a fraction of a second.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":90}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"burst","rate":450,"duration":200,"interval":5000}$j$::jsonb,
  15000,
  1040,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.98,"label":"At least 98% of passengers are notified","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":100,"label":"95% of notifications arrive within 100ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  440,
  FALSE,
  $j$["Notifications don't trickle in — every status change fires to hundreds of trackers at once. Watch what happens to a synchronous Database's own backlog.","A Database's own backlog can absorb the burst for free — it isn't billed. So why would inserting a Message Queue ever be worth it?","The passenger is still waiting the whole time their notification sits in a Database's backlog. Is there a component that can confirm it before the actual write has happened?"]$j$::jsonb,
  $j$["A synchronous backend can absorb a burst it can't otherwise handle just by raising its own backlog — but every request in that backlog makes the caller wait, and at high enough volume that wait gets severe, not just noticeable.","A Message Queue confirms a request the instant it's durably admitted, decoupling the caller's wait from how long the actual downstream write takes.","Once a queue is absorbing bursts, the backend behind it only needs to be sized for the sustained average rate, not any single burst's peak."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A Message Queue between the API Server and Database, confirming every notification the instant it's durably queued — with the Database itself sized for the average rate, not any single burst's peak.","editorial":["A Database's own backlog can absorb this burst for free — it isn't billed. Raising it large enough to admit every notification directly does work, functionally. But the passenger is waiting synchronously the whole time their notification sits in that backlog, and at this volume the wait is severe — nearly 700ms at the tail, not just noticeable.","Brute-force sizing the Database's own connection count high enough to drain the burst almost instantly does fix the latency too — but connections are billed, and provisioning enough of them costs far more than the traffic's own average rate would ever justify.","A Message Queue confirms the passenger's notification the instant it's durably queued, regardless of how long the eventual database write takes. The Database behind the queue only ever needs to keep up with the sustained average rate — a smaller, cheaper Database, at near-zero extra cost for the queue itself."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":90}},{"id":"api","type":"api","label":"API Server","position":{"x":320,"y":200},"config":{"maxConcurrent":10,"maxQueueLength":200,"processingTimeMs":1}},{"id":"mq","type":"message_queue","label":"Message Queue","position":{"x":560,"y":200},"config":{"consumerCount":10,"maxQueueLength":400,"dispatchTimeMs":1}},{"id":"db","type":"database","label":"Database","position":{"x":800,"y":200},"config":{"maxConnections":2,"maxQueueLength":50,"processingTimeMs":1}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"mq"},{"source":"mq","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$coupon-code-redemption$j$,
  1,
  'PUBLISHED',
  $j$Coupon Code Redemption$j$,
  4,
  $j$["caching"]$j$::jsonb,
  NULL,
  $j$A single viral coupon code is spreading across social media, and everyone's rushing to redeem it before it expires — a huge crowd, all checking the validity of the same handful of active codes. Every redemption check that reaches the database for a code that hasn't changed since the last check is money spent for nothing. Engineering's job is to keep checkout feeling instant for a crowd this size, without paying database rates for traffic that's really just re-asking the same few questions.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":450,"keyPoolSize":40}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":450}$j$::jsonb,
  8000,
  1060,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.98,"label":"At least 98% of redemption checks succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":40,"label":"95% of checks complete within 40ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  600,
  FALSE,
  $j$["Everyone rushing to redeem is checking one of a small handful of active codes. What does that mean for how often the database actually needs to be asked?","A properly-sized API Server and Database, with no cache at all, already clears both the success-rate and latency bars. Check what it costs.","The full set of currently-active coupon codes is small enough to hold entirely in a modest cache."]$j$::jsonb,
  $j$["At high enough volume, even a functionally correct, properly-sized build can be nearly double the budget — sizing alone doesn't fix a cost problem caused by repeat work.","A cache absorbs the most benefit exactly when traffic is skewed toward a small set of hot keys — a single viral code, checked by a huge crowd, is about as skewed as it gets.","A cache sized to hold the entire hot set turns nearly every request into a hit, collapsing the database's real workload — and its cost — down to almost nothing."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A cache sized to hold every currently-active coupon code — so virtually every redemption check is answered without touching the database — in front of a minimally-sized database.","editorial":["A properly-sized API Server and Database, with no cache at all, handles this traffic just fine functionally. The problem is purely cost, and at this volume it's dramatic — a capacity-adequate build here costs nearly twice the budget.","A cache sized to hold every active code turns almost every check into a hit. Once that's true, the database behind it barely needs to do anything — its own sizing (and its cost) collapses along with the volume actually reaching it.","Sizing alone genuinely cannot solve this within budget — the cache isn't just the cheaper option here, it's the only one that fits."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":450,"keyPoolSize":40}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":5,"maxQueueLength":40,"processingTimeMs":2}},{"id":"cache","type":"cache","label":"Cache","position":{"x":600,"y":200},"config":{"capacity":40,"evictionPolicy":"lru","ttlMs":0}},{"id":"db","type":"database","label":"Database","position":{"x":860,"y":200},"config":{"maxConnections":2,"maxQueueLength":30,"processingTimeMs":4}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"cache"},{"source":"cache","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$fitness-tracker-step-sync$j$,
  1,
  'PUBLISHED',
  $j$Fitness Tracker Step Sync$j$,
  4,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$Millions of fitness trackers phone home with step counts every few seconds — pure write volume, spread across a huge number of independent devices, with nothing here that repeats often enough for a cache to help. Engineering's job is to make sure every sync actually lands, on a budget that scales sanely with device count instead of linearly with however many connections the database happens to have.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":470,"keyPoolSize":1200}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":470}$j$::jsonb,
  8000,
  1070,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.98,"label":"At least 98% of syncs are written","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":60,"label":"95% of writes complete within 60ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  850,
  FALSE,
  $j$["Millions of independent devices, each syncing their own steps — nothing here is a good candidate for a cache. What else determines how much a database can absorb?","A properly-sized SQL database can clear both the success-rate and latency bars here. Check what it costs against the budget.","The Database entity has a `type` field. What does switching it actually change, and does it cost anything extra?"]$j$::jsonb,
  $j$["Not every high-volume workload is a caching problem — pure write traffic across a huge key space gives a cache nothing to exploit.","A database's `type` (SQL vs NoSQL) changes its effective connection ceiling and per-query time at no extra cost — picking the right one can be the difference between clearing a budget and blowing it.","Two builds can both be functionally correct — the deciding factor is often which one the budget actually allows."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A NoSQL-type database, tightly sized — its connection-ceiling and query-time multiplier clears the same write volume a much larger SQL pool would need, at a fraction of the cost.","editorial":["This traffic doesn't repeat — millions of devices, each writing their own step count, means there's no hot key for a cache to exploit.","A properly-sized SQL database clears the success-rate and latency bars just fine functionally. The problem is purely cost: reaching that same throughput ceiling with a SQL connection pool costs more than the budget allows.","Switching the Database's own `type` to NoSQL applies a real connection-ceiling and query-time multiplier — several times the effective throughput of the same pool size, at zero extra cost."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":470,"keyPoolSize":1200}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"maxConcurrent":4,"maxQueueLength":50,"processingTimeMs":1}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"type":"nosql","maxConnections":3,"maxQueueLength":50,"processingTimeMs":1}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$api-gateway-slowdown$j$,
  1,
  'PUBLISHED',
  $j$API Gateway Slowdown$j$,
  4,
  $j$["system-design"]$j$::jsonb,
  NULL,
  $j$Every service behind the API gateway has gotten slower, and the on-call dashboard shows both the gateway's own API layer and the backing database running hot. The obvious instinct is to scale up whichever looks busiest — but at this traffic volume, scaling the wrong tier gets expensive fast for no real improvement. Engineering's job is to find the actual ceiling before spending real budget on either.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":460,"keyPoolSize":900}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":460}$j$::jsonb,
  8000,
  1080,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.97,"label":"At least 97% of requests succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":150,"label":"95% of requests complete within 150ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  850,
  FALSE,
  $j$["Both the API Server and the Database show high utilization in an unconfigured build. Are they necessarily two independent problems?","Try raising only the API Server's own concurrency, leaving the Database untouched. Does that actually move success rate?","Now try the opposite: raise only the Database, leave the API Server at its default. Compare."]$j$::jsonb,
  $j$["A saturated-looking component can just be waiting on the real bottleneck downstream — utilization tells you something is busy, not why.","Verify a fix actually helps before spending budget on it — raising the wrong tier's capacity can cost more while barely moving the outcome.","Once the real ceiling is identified, fixing just that one component is often enough."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"The API Server left near its default — the Database, deliberately sized to actually clear the traffic, was always the real ceiling.","editorial":["An unconfigured build shows both tiers at high utilization — the natural instinct is to treat that as two separate shortages. It isn't: the API Server's own concurrent slots are occupied waiting on a struggling Database response.","The tell is what happens when you raise only the API Server's concurrency: success rate barely moves, and the build costs more for almost the same result.","Raising only the Database fixes the whole picture at once. Utilization is a symptom, not a diagnosis; verify a fix actually helps before spending budget chasing the component that merely looks busy."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":460,"keyPoolSize":900}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{"maxConcurrent":4,"maxQueueLength":30,"processingTimeMs":2}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{"maxConnections":6,"maxQueueLength":40,"processingTimeMs":5}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$trending-product-search$j$,
  1,
  'PUBLISHED',
  $j$Trending Product Search$j$,
  4,
  $j$["caching","system-design"]$j$::jsonb,
  NULL,
  $j$A shopping app's search bar is dominated by a handful of trending products during a big sale — nearly everyone typing a query lands on one of the same few items. The product catalog's storage engine has always been a little slow per-query, and under this load that slowness is now the whole story: even a well-provisioned connection pool can't out-buy a query that's simply too slow, one at a time. Engineering's job is to keep search feeling instant for a crowd this size, on a budget that doesn't assume infinite headroom.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":210,"keyPoolSize":320}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":210}$j$::jsonb,
  8000,
  1100,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.98,"label":"At least 98% of searches succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":45,"label":"95% of searches complete within 45ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  470,
  FALSE,
  $j$["Most searches during the sale land on the same handful of trending products. What does that suggest about how often the database actually needs to be asked?","Try giving the Database as many connections as it could reasonably want, with no cache at all. Does that alone bring latency under the bar?","A Database's own processing time per query doesn't shrink just because it has more connections. Is there a lever that changes the per-query time itself?"]$j$::jsonb,
  $j$["A database's own per-query processing time is a floor that raw connection count can't buy down — it's a separate lever from capacity.","A cache and a database-type choice solve different problems — one cuts how often the database gets asked at all, the other changes how long each ask takes. A workload can need both at once.","Not every requirement in a scenario is a cost constraint — a structural latency floor can rule out an option regardless of budget."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A cache absorbing most repeat lookups, in front of a NoSQL-type database — its lower per-query time is what actually clears the latency bar, no amount of SQL connections can buy that down.","editorial":["A cache alone gets most of the way there: it cuts how often the database gets asked at all. But even a generously-connected SQL database, fronted by a cache, still misses the latency bar — adding connections relieves queueing, it doesn't change how long any single query takes.","Switching the Database's own `type` to NoSQL applies a real per-query processing-time multiplier, independent of how many connections are configured. That's what actually closes the latency gap SQL structurally can't.","This scenario needs both levers at once, and the margins are genuinely tight — that's honest for requiring two things to be right simultaneously, not an oversight."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":210,"keyPoolSize":320}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":6,"maxQueueLength":50,"processingTimeMs":1}},{"id":"cache","type":"cache","label":"Cache","position":{"x":600,"y":200},"config":{"capacity":70,"evictionPolicy":"lru","ttlMs":0}},{"id":"db","type":"database","label":"Database","position":{"x":860,"y":200},"config":{"type":"nosql","maxConnections":2,"maxQueueLength":40,"processingTimeMs":18}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"cache"},{"source":"cache","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$global-leaderboard-updates$j$,
  1,
  'PUBLISHED',
  $j$Global Leaderboard Updates$j$,
  5,
  $j$["caching","system-design"]$j$::jsonb,
  NULL,
  $j$A competitive game shows a live global leaderboard — millions of players, but at any moment almost everyone checking it cares about the same few hundred top ranks. The leaderboard's storage engine has always been a little slow per-query, and under this load that slowness is now the whole story: even a well-provisioned connection pool can't out-buy a query that's simply too slow, one at a time. Engineering's job is to keep the board feeling instant for a crowd this size, on a budget that doesn't assume infinite headroom.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":230,"keyPoolSize":350}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"constant","rate":230}$j$::jsonb,
  8000,
  1050,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.98,"label":"At least 98% of leaderboard loads succeed","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":46,"label":"95% of leaderboard loads complete within 46ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","keyPoolSize"]}$j$::jsonb,
  500,
  FALSE,
  $j$["Most players checking the leaderboard are looking at the same top ranks. What does that suggest about how often the database actually needs to be asked?","Try giving the Database as many connections as it could reasonably want, with no cache at all. Does that alone bring latency under the bar?","A Database's own processing time per query doesn't shrink just because it has more connections. Is there a lever that changes the per-query time itself?"]$j$::jsonb,
  $j$["A database's own per-query processing time is a floor that raw connection count can't buy down — it's a separate lever from capacity.","A cache and a database-type choice solve different problems — one cuts how often the database gets asked at all, the other changes how long each ask takes. A workload can need both at once.","Requiring two things to be right simultaneously costs more headroom than requiring just one — the hardest scenarios in this catalogue don't have comfortable margins to spare."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A cache absorbing most repeat lookups, in front of a NoSQL-type database — its lower per-query time is what actually clears the latency bar, no amount of SQL connections can buy that down.","editorial":["A cache alone gets most of the way there: it cuts how often the database gets asked at all. But even a generously-connected SQL database, fronted by a cache, still misses the latency bar — adding connections relieves queueing, it doesn't change how long any single query takes.","Switching the Database's own `type` to NoSQL applies a real per-query processing-time multiplier, independent of how many connections are configured. That's what actually closes the latency gap SQL structurally can't.","This scenario needs both levers at once, tuned tightly, and the margins are genuinely thin — that's honest for the hardest problem in this catalogue, not an oversight."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":230,"keyPoolSize":350}},{"id":"api","type":"api","label":"API Server","position":{"x":340,"y":200},"config":{"maxConcurrent":6,"maxQueueLength":50,"processingTimeMs":1}},{"id":"cache","type":"cache","label":"Cache","position":{"x":600,"y":200},"config":{"capacity":80,"evictionPolicy":"lru","ttlMs":0}},{"id":"db","type":"database","label":"Database","position":{"x":860,"y":200},"config":{"type":"nosql","maxConnections":2,"maxQueueLength":40,"processingTimeMs":18}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"cache"},{"source":"cache","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$wildfire-alert-broadcast$j$,
  1,
  'PUBLISHED',
  $j$Wildfire Alert Broadcast$j$,
  5,
  $j$["message-queues"]$j$::jsonb,
  NULL,
  $j$When a wildfire alert is issued for a region, every resident's phone in that area needs an emergency push notification within seconds — hundreds of thousands of devices, all at once, then quiet until the next alert. A notification that arrives late, or not at all, is not an inconvenience here — it's the entire point of the system failing. Engineering's job is to make every alert land near-instantly for a crowd this size, without paying to keep the backend permanently sized for an emergency that, thankfully, isn't constant.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":100}},{"id":"api","type":"api","label":"API Server","position":{"x":400,"y":200},"config":{}},{"id":"db","type":"database","label":"Database","position":{"x":720,"y":200},"config":{}}]$j$::jsonb,
  $j$[{"source":"client","target":"api"},{"source":"api","target":"db"}]$j$::jsonb,
  $j${"type":"burst","rate":500,"duration":200,"interval":5000}$j$::jsonb,
  15000,
  1090,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.99,"label":"At least 99% of residents are notified","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":40,"label":"95% of alerts arrive within 40ms","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  470,
  FALSE,
  $j$["Alerts don't trickle in — an entire region's worth of phones need notifying at once. Watch what a synchronous Database's own backlog does with that.","A Database's own backlog can absorb the burst for free — it isn't billed. So why would inserting a Message Queue ever be worth it?","The resident is still waiting the whole time their notification sits in a Database's backlog. Is there a component that can confirm it before the actual write has happened?"]$j$::jsonb,
  $j$["A synchronous backend can absorb a burst it can't otherwise handle just by raising its own backlog — but at high enough volume, the resulting wait isn't just noticeable, it's catastrophic.","A Message Queue confirms a request the instant it's durably admitted, decoupling the caller's wait from how long the actual downstream write takes.","Once a queue is absorbing bursts, the backend behind it only needs to be sized for the sustained average rate, not any single burst's peak."]$j$::jsonb,
  NULL,
  NULL,
  $j${"summary":"A Message Queue between the API Server and Database, confirming every alert the instant it's durably queued — with the Database itself sized for the average rate, not any single burst's peak.","editorial":["A Database's own backlog can absorb this burst for free. Raising it large enough to admit every alert directly does work, functionally — but the resident is waiting synchronously the whole time, and at this volume the wait is catastrophic: nearly 20x the latency bar.","Brute-force sizing the Database's own connection count high enough to drain the burst almost instantly does fix the latency — but connections are billed, and provisioning enough of them nearly doubles the budget.","A Message Queue confirms the resident's alert the instant it's durably queued, regardless of how long the eventual database write takes. The Database behind the queue only ever needs to keep up with the sustained average rate — a smaller, cheaper Database, at near-zero extra cost for the queue itself."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":200},"config":{"requestRate":100}},{"id":"api","type":"api","label":"API Server","position":{"x":320,"y":200},"config":{"maxConcurrent":10,"maxQueueLength":200,"processingTimeMs":1}},{"id":"mq","type":"message_queue","label":"Message Queue","position":{"x":560,"y":200},"config":{"consumerCount":10,"maxQueueLength":450,"dispatchTimeMs":1}},{"id":"db","type":"database","label":"Database","position":{"x":800,"y":200},"config":{"maxConnections":2,"maxQueueLength":50,"processingTimeMs":1}}],"connections":[{"source":"client","target":"api"},{"source":"api","target":"mq"},{"source":"mq","target":"db"}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$customer-support-agent$j$,
  1,
  'PUBLISHED',
  $j$Customer Support Refund Agent$j$,
  3,
  $j$["tool-use","human-in-the-loop","agentic-system-design"]$j$::jsonb,
  NULL,
  $j$An e-commerce company wants an agent to handle refund requests automatically — read the request, decide whether it's legitimate, and issue the refund. Legal and finance have one non-negotiable policy: no refund goes out without a human actually reviewing the agent's decision first. The agent can be as fast and as automated as engineering wants, right up until the moment it's about to spend the company's money.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":3}}]$j$::jsonb,
  $j$[]$j$::jsonb,
  $j${"type":"constant","rate":3}$j$::jsonb,
  20000,
  100,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.9,"label":"At least 90% of refund requests reach a real outcome","unit":"%"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  NULL,
  TRUE,
  $j$["\"Never issue a refund without a human reviewing it first\" is a sentence about the architecture, not a number in a config field. Which primitive actually enforces that, and where does it have to sit relative to the tool that issues the refund?","Leave every reliability dial (Hallucination Rate, Denial Rate, Failure Rate, ...) at its default and this fails no matter how you size anything downstream. Every entity here rolls its own failure checks twice — once on the way out, once on the way back — so a dial reading '10%' in the Inspector is a real ~19% in practice. What happens if you actually tune those down instead of just wiring things together?","Approval Latency is a real cost paid by every request that reaches the gate, not a rounding error. If a human takes 4 seconds to review a case and the gate can only review 5 cases at once, how many requests per second can it actually clear — and does that number even reach the traffic this scenario hands you?","The success-rate bar doesn't care whether a request failed because a human said no or because your architecture skipped the gate entirely. Those are two very different problems with two very different fixes."]$j$::jsonb,
  $j$["Reversibility-weighted risk, in practice: a human_in_loop_gate isn't a generic safety checkbox, it's a specific primitive that has to sit between a decision and the irreversible action that decision triggers — and this app's own architecture gate can tell the difference between 'gated' and 'not gated.'","A gate's own capacity is bound by how long a real review takes, the same admit-queue-reject shape every bounded entity here already uses — sizing it means reasoning about Approval Latency × concurrent reviewers, not just cranking a number up.","Every agentic entity here rolls its own reliability dials on both the request leg and the response leg — a documented, engine-wide simplification worth knowing about before it quietly doubles your effective failure rate."]$j$::jsonb,
  $j${"prompt":"The gate reviews at most Max Concurrent cases at once, each taking roughly Approval Latency to clear. At 3 req/s arriving and a 4000ms Approval Latency, roughly how many cases does the gate need to be able to hold open simultaneously just to keep up on average — before a single burst is considered?","worked":"In steady state, the number of cases in flight at once is arrival rate × time each one takes: 3 req/s × 4s = 12. Max Concurrent needs real headroom above that raw number, not just enough to match it exactly — a pool sized to the bare average has nowhere for a burst to go but the queue, then rejection, the same lesson every other bounded entity in this app already teaches, just with a human's review time standing in for a query's."}$j$::jsonb,
  $j${"template":"This run landed at {{successRate}} success with a p95 latency of {{p95Latency}} — and that latency number is not a bug to chase down. A real human reviewing a real refund request takes real time; a fast-looking refund agent that skips the review isn't a better architecture, it's a policy violation the metrics can't see but the architecture gate can."}$j$::jsonb,
  $j${"summary":"A tuned llm_call deciding, gated by a properly-sized human_in_loop_gate, before a tuned tool_call actually issues the refund.","editorial":["The policy itself only has one correct shape: llm_call decides, human_in_loop_gate reviews, tool_call acts — in that order, with nothing skipping the middle step. There's no config value that substitutes for actually wiring the gate in; the architecture check fails a build that reaches the refund tool_call any other way, regardless of how good its numbers look.","Once the gate is wired in, the next failure mode is subtler: every default reliability dial left untouched compounds into a real failure floor, because every entity here rolls its own checks on both the outbound and the response leg. Tuning Hallucination Rate, Denial Rate, and the tool's own failure dials down isn't cosmetic here — it's the difference between a passing build and one stuck under 60% success no matter how the gate is sized.","The gate's own capacity is the last real lever: Approval Latency is a fixed cost per case, and Max Concurrent has to hold enough cases open at once to actually absorb the traffic this scenario hands you, not just the bare average.","A common near-miss: sizing the gate generously but leaving Denial Rate and the tool's own dials at their defaults, assuming capacity was the only thing standing between a failing and a passing build. It isn't — both have to be addressed."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":3}},{"id":"llm1","type":"llm_call","label":"LLM Call","position":{"x":380,"y":220},"config":{"hallucinationRate":0.01,"schemaFailureRate":0.01}},{"id":"gate1","type":"human_in_loop_gate","label":"Human-in-the-Loop Gate","position":{"x":680,"y":220},"config":{"approvalLatencyMs":4000,"approvalLatencyJitterMs":1000,"denialRate":0.02,"maxConcurrent":30}},{"id":"tool1","type":"tool_call","label":"Tool Call","position":{"x":980,"y":220},"config":{"failureRate":0.01,"schemaFailureRate":0.01,"hallucinatedInvocationRate":0.01,"silentFailureRate":0.01}}],"connections":[{"source":"client","target":"llm1","latencyMs":5},{"source":"llm1","target":"gate1","latencyMs":5},{"source":"gate1","target":"tool1","latencyMs":5}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$coding-agent$j$,
  1,
  'PUBLISHED',
  $j$Autonomous Coding Agent$j$,
  4,
  $j$["tool-use","human-in-the-loop","agentic-system-design"]$j$::jsonb,
  NULL,
  $j$An engineering team wants an agent that can take a small code-change request, write and test the change itself, and — only once it's confident and a human has actually signed off — deploy it. Writing and testing code is cheap and fully reversible; deploying it isn't. The team wants the agent to iterate freely on the cheap part and stop hard before the expensive one.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":1.5}}]$j$::jsonb,
  $j$[]$j$::jsonb,
  $j${"type":"constant","rate":1.5}$j$::jsonb,
  20000,
  200,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.9,"label":"At least 90% of change requests reach a real outcome","unit":"%"},{"id":"total-iterations","metric":"totalIterations","comparator":"lte","threshold":20,"label":"Total Iterations stays bounded — deny-first, not retry-forever"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  NULL,
  TRUE,
  $j$["Reflection (llm_call -> guardrail_validator, wrapped in a Sequential Agent Orchestrator) is the iterate-and-test loop; the deploy itself needs a second, harder gate after it — the same 'not every action deserves the same check' idea customerSupportAgent teaches, now with two different actions in one build.","Max Iterations isn't just 'how many tries before giving up' — a high value passes more often but lets one flaky session cause a real pile of downstream retries. What does the Total Iterations constraint actually measure, and what does a 'deny-first' agent's number look like next to a lenient one's?","Every dial here doubles its effective rate across the request and response leg, the same as every other entity in this domain — a Rejection Rate or Denial Rate that reads reasonable in the Inspector can still be the reason a wired-correctly build fails.","The gate's own Approval Latency and Max Concurrent matter here too, same math as any other approval-latency-bound entity: how many deploys can one reviewer clear per second at this traffic?"]$j$::jsonb,
  $j$["Claude Code's own real design in one sentence: iterate freely and cheaply where mistakes are reversible, gate hard exactly once before the one action that isn't — not a uniform check applied everywhere.","Max Iterations is a genuine trade-off, not a free dial: too low fails fast on transient noise, too high hides a real cost (this scenario's own Total Iterations metric) behind a passing success rate.","Reflection's retry loop and the irreversible-action gate are two independently-composed primitives, not one mechanism — a session can retry the cheap part as many times as its budget allows while still only ever reaching the expensive part once, gated."]$j$::jsonb,
  $j${"prompt":"At 1.5 req/s and a Guardrail Validator Rejection Rate around 15%, roughly how many llm_call attempts per second does a Sequential Agent Orchestrator's retry loop actually generate against the guardrail, before any of it reaches the gate at all?","worked":"Most sessions pass on the first or second attempt at a real ~15-25% effective rejection rate (doubled by the request/response-leg roll, so a configured 15% reads closer to 28% in practice) — call it roughly 1.3-1.5x the raw 1.5 req/s reaching the guardrail per second on average, once retries are folded in. That's still comfortably inside every entity's default capacity here; the real constraint this scenario is testing is Total Iterations staying bounded, not raw throughput."}$j$::jsonb,
  $j${"template":"{{successRate}} success with {{totalIterations}} total iterations across the whole run — read those two numbers together, not separately. A build that passes on success rate alone by retrying aggressively is hiding its real cost in the iteration count; a build that's both reliable *and* bounded is the one that actually earned the 'deny-first' label."}$j$::jsonb,
  $j${"summary":"A tuned Reflection loop (Agent Orchestrator -> LLM Call -> Guardrail Validator) with a modest Max Iterations, gated by a human_in_loop_gate before the one Tool Call that deploys.","editorial":["The shape is Reflection, plus one more gate: Client -> Agent Orchestrator (Sequential) -> LLM Call -> Guardrail Validator -> Human-in-the-Loop Gate -> Tool Call. The orchestrator's own existing retry mechanism (from Phase 2/3) handles the 'iterate until tests pass' part for free — a rejected guardrail check propagates back through llm_call to the orchestrator, which retries in place, no new orchestration logic needed.","Max Iterations at 3 is the deliberate middle: low enough that Total Iterations stays well under this scenario's own 20 bound, high enough to actually absorb the guardrail's real rejection rate without failing sessions that would have passed on a second try.","Every reliability dial tuned down together is what gets success rate from the 60s into the high 90s — Hallucination/Schema Failure Rate on the LLM Call, Denial Rate on the gate, and the Tool Call's own four failure dials all compound, the same lesson customerSupportAgent teaches, now stacked on top of a genuine retry loop.","A common near-miss: raising Max Iterations instead of tuning the reliability dials, since more retries does eventually push success rate up. It also blows straight through the Total Iterations bound — a lenient Max Iterations of 8 on this same traffic reaches 62 total iterations, more than 3x this scenario's own limit, even while passing on success rate alone."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":1.5}},{"id":"orch1","type":"agent_orchestrator","label":"Agent Orchestrator","position":{"x":340,"y":220},"config":{"routingMode":"sequential","maxIterations":3,"maxConcurrent":20}},{"id":"llm1","type":"llm_call","label":"LLM Call","position":{"x":600,"y":220},"config":{"hallucinationRate":0.01,"schemaFailureRate":0.01,"processingTimeMs":300}},{"id":"guard1","type":"guardrail_validator","label":"Guardrail Validator","position":{"x":860,"y":220},"config":{"mode":"gate","rejectionRate":0.15,"processingTimeMs":100}},{"id":"gate1","type":"human_in_loop_gate","label":"Human-in-the-Loop Gate","position":{"x":1120,"y":220},"config":{"approvalLatencyMs":3000,"approvalLatencyJitterMs":800,"denialRate":0.02,"maxConcurrent":15}},{"id":"tool1","type":"tool_call","label":"Tool Call","position":{"x":1380,"y":220},"config":{"failureRate":0.01,"schemaFailureRate":0.01,"hallucinatedInvocationRate":0.01,"silentFailureRate":0.01}}],"connections":[{"source":"client","target":"orch1","latencyMs":5},{"source":"orch1","target":"llm1","latencyMs":5},{"source":"llm1","target":"guard1","latencyMs":5},{"source":"guard1","target":"gate1","latencyMs":5},{"source":"gate1","target":"tool1","latencyMs":5}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$research-assistant$j$,
  1,
  'PUBLISHED',
  $j$Research Assistant$j$,
  3,
  $j$["retrieval","agentic-system-design"]$j$::jsonb,
  NULL,
  $j$A research team wants an assistant that can answer questions over their internal knowledge base — but most of what they actually ask isn't simple lookup. It's questions like 'which of our vendors also supply our biggest competitor' or 'what changed between this decision and the one it replaced' — the kind of answer that lives in the relationships between documents, not inside any single one of them.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":10,"relationshipQueryRate":0.6}}]$j$::jsonb,
  $j$[]$j$::jsonb,
  $j${"type":"constant","rate":10}$j$::jsonb,
  15000,
  300,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.7,"label":"At least 70% of research questions are actually answered","unit":"%"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate","relationshipQueryRate"]}$j$::jsonb,
  NULL,
  FALSE,
  $j$["60% of the traffic this scenario hands you needs relationship reasoning across documents, not lookup inside one. Which of the four Retriever modes is actually built to traverse relationships instead of comparing chunk similarity?","Lowering Miss Rate on Pipeline mode doesn't fix a structural ceiling — Relationship Penalty Multiplier is multiplying whatever Miss Rate you set, on 60% of your traffic, no matter how low you push it.","Adaptive mode isn't a fifth, separately-tuned architecture — it's a router that delegates to Pipeline's or GraphRAG's own real numbers per query. What does that actually buy you on traffic that's a mix of both kinds of question?"]$j$::jsonb,
  $j$["No amount of tuning closes a structural gap — Pipeline (chunk similarity) and GraphRAG (relationship traversal) aren't the same idea at two different quality settings, they answer genuinely different kinds of questions.","The right retrieval architecture depends on the shape of the traffic, not a general 'which one is best' ranking — the same GraphRAG that wins decisively here would be paying a real, unnecessary cost on traffic that's mostly simple lookup.","Adaptive's real value: it's not a compromise between two options, it's genuine per-query delegation to whichever one actually fits."]$j$::jsonb,
  $j${"prompt":"Pipeline mode's Miss Rate defaults to 12%, multiplied by a Relationship Penalty of 4x on a relationship-shaped query. At a 60% Relationship Query Rate, roughly what fraction of all traffic ends up hitting that penalized miss rate, and how bad does the effective miss rate get on just that slice?","worked":"12% x 4 = 48% effective miss rate on the 60% of traffic that needs relationship reasoning — under half of that slice succeeds at all, dragging the overall success rate down even though the other 40% (ordinary lookups) still clears easily. The problem isn't a bad roll of the dice, it's that nearly half of the traffic that matters most is structurally miss-prone under this mode."}$j$::jsonb,
  $j${"template":"This run landed at {{successRate}} success. If that number is well under 70%, check which Retriever mode is wired in before touching a single other dial — this scenario's gap between a passing and a failing build is a mode choice, not a tuning problem."}$j$::jsonb,
  $j${"summary":"GraphRAG (or Adaptive) mode, wired directly between the Client and an LLM Call.","editorial":["The fix is a single dial: Retriever Mode set to GraphRAG (or Adaptive) instead of Pipeline. Nothing else about the topology needs to change — the same two-node Client -> Retriever -> LLM Call shape works under any mode, only the retrieval architecture underneath it differs.","GraphRAG pays a real, constant cost even on the 40% of traffic that didn't need it (higher Graph Traversal Time, a worse base Miss Rate than Pipeline on an ordinary query) — it wins here specifically because the traffic mix rewards that trade.","Adaptive edges GraphRAG out slightly on this exact traffic by routing the easier 40% through Pipeline's cheaper path instead of paying GraphRAG's constant cost on queries that didn't need it — the closest thing to 'best of both' this entity offers, since it's genuinely delegating to each mode's own real behavior per query.","A common near-miss: assuming a lower Miss Rate on Pipeline mode is 'good enough' — it isn't, because the penalty multiplier scales whatever Miss Rate is configured. This traffic needs a different retrieval architecture, not a better-tuned version of the wrong one."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":10,"relationshipQueryRate":0.6}},{"id":"ret1","type":"retriever","label":"Retriever","position":{"x":380,"y":220},"config":{"mode":"adaptive"}},{"id":"llm1","type":"llm_call","label":"LLM Call","position":{"x":680,"y":220},"config":{"hallucinationRate":0.02,"schemaFailureRate":0.02}}],"connections":[{"source":"client","target":"ret1","latencyMs":5},{"source":"ret1","target":"llm1","latencyMs":5}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$autonomous-ops-agent$j$,
  1,
  'PUBLISHED',
  $j$Autonomous Ops Agent$j$,
  5,
  $j$["multi-agent-orchestration","human-in-the-loop","agentic-system-design"]$j$::jsonb,
  NULL,
  $j$An SRE team wants an agent that responds to production incidents on its own: pull the relevant diagnostics, hand the incident to a decision-making peer agent, and — once a human has actually signed off — take the corrective action (a restart, a rollback, whatever the incident calls for). Diagnostics are read-only and safe to run freely; the corrective action is not, and needs the same real review this team would want before any human engineer touched production at 3am.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":4}}]$j$::jsonb,
  $j$[]$j$::jsonb,
  $j${"type":"constant","rate":4}$j$::jsonb,
  20000,
  400,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.95,"label":"At least 95% of incidents reach a real outcome","unit":"%"},{"id":"p95-latency","metric":"p95Latency","comparator":"lte","threshold":25000,"label":"95% of incidents resolve within 25s","unit":"ms"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  NULL,
  TRUE,
  $j$["Two Agent Orchestrators wired as peers — one dispatching to the other, not through a shared parent — is Multi-Agent Collaboration, per this app's own primitive. What does the first orchestrator's Routing Mode need to be, to run diagnostics and hand off to its peer at the same time rather than one after the other?","The corrective action is the only irreversible thing in this whole build — everything else (pulling diagnostics, deciding) is investigation, not action. Where's the one place a human_in_loop_gate actually needs to sit?","A p95 latency this high isn't automatically wrong — a real human review takes real time. But there's a real difference between 'the review itself is slow' and 'requests are queueing behind a reviewer pool that's too small for the traffic.' Which one is this?","Nothing stops you from wiring the diagnostic Retriever's result straight into the decision with no check on it. What happens to a hallucinated or wrong diagnostic result under that build, versus one with a Guardrail Validator in between?"]$j$::jsonb,
  $j$["Orchestrator-Worker and Multi-Agent Collaboration aren't mutually exclusive patterns — a real system composes them: one orchestrator's 'worker' can itself be another orchestrator running its own internal chain.","Reversibility-weighted risk again, at multi-agent scale: read-only investigation stays ungated and can run freely; the one real action gets the one real gate, not a blanket check applied everywhere.","An unverified result trusted downstream (docs/Agentic_AI.md's error-cascade failure mode) is a wiring gap, not a metrics failure — a build can pass every constraint here while still having no check between a diagnostic result and the decision that acts on it."]$j$::jsonb,
  $j${"prompt":"The gate's Approval Latency defaults to 3000ms. At 4 req/s of incidents needing a human decision, roughly how many reviews does the gate need to hold open at once just to keep up with the average arrival rate?","worked":"4 req/s x 3s = 12 reviews in flight on average — Max Concurrent needs real headroom above that raw number (not exactly 12) to absorb any burst without the backlog growing unbounded, the same admit-queue-reject reasoning every bounded entity in this app already uses."}$j$::jsonb,
  $j${"template":"{{successRate}} success at a p95 of {{p95Latency}} — if that latency number is well above what a human reviewer's own delay explains, the gate is queueing, not reviewing. Check Max Concurrent before assuming Approval Latency itself is the problem."}$j$::jsonb,
  $j${"summary":"One orchestrator fanning out (Parallel) to a read-only diagnostics Retriever and a peer orchestrator, which itself decides, gates, then acts — Orchestrator-Worker and Multi-Agent Collaboration composed in one build.","editorial":["orchA (Parallel mode) dispatches to two targets at once: ret1, a Retriever pulling diagnostics, and orchB, a second Agent Orchestrator running its own internal chain. That's Orchestrator-Worker (the parallel fan-out) and Multi-Agent Collaboration (a peer orchestrator as one of the workers) in the same topology, not two separate builds.","orchB (Sequential mode) is where the actual decision happens: LLM Call decides, Human-in-the-Loop Gate reviews, Tool Call acts. This is the only tool_call anywhere in the build — diagnostics stay read-only on purpose, so there's exactly one action that needs gating and it's gated.","Gate Max Concurrent at 20 is what actually clears the p95 constraint — the default of 5 still passes on success rate (nothing here rejects outright, everything just queues), but its p95 balloons past 60 seconds. Sizing the gate for real traffic, not just leaving it at whatever the Inspector defaults to, is the whole difference.","A common near-miss: wiring ret1's diagnostic result straight into orchB's decision with nothing checking it first. This build passes every constraint here without a Guardrail Validator in that path — worth building once with one anyway, to see how a bad diagnostic result gets caught at the boundary instead of silently driving the wrong action."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":4}},{"id":"orchA","type":"agent_orchestrator","label":"Agent Orchestrator (Diagnostics)","position":{"x":380,"y":220},"config":{"routingMode":"parallel","maxConcurrent":20}},{"id":"ret1","type":"retriever","label":"Retriever","position":{"x":680,"y":80},"config":{"mode":"pipeline","missRate":0.05}},{"id":"orchB","type":"agent_orchestrator","label":"Agent Orchestrator (Decision)","position":{"x":680,"y":320},"config":{"routingMode":"sequential","maxConcurrent":20}},{"id":"llm1","type":"llm_call","label":"LLM Call","position":{"x":940,"y":320},"config":{"hallucinationRate":0.03,"schemaFailureRate":0.02}},{"id":"gate1","type":"human_in_loop_gate","label":"Human-in-the-Loop Gate","position":{"x":1200,"y":320},"config":{"approvalLatencyMs":3000,"approvalLatencyJitterMs":800,"denialRate":0.05,"maxConcurrent":20}},{"id":"tool1","type":"tool_call","label":"Tool Call","position":{"x":1460,"y":320},"config":{"failureRate":0.02,"schemaFailureRate":0.02}}],"connections":[{"source":"client","target":"orchA","latencyMs":5},{"source":"orchA","target":"ret1","latencyMs":5},{"source":"orchA","target":"orchB","latencyMs":5},{"source":"orchB","target":"llm1","latencyMs":5},{"source":"llm1","target":"gate1","latencyMs":5},{"source":"gate1","target":"tool1","latencyMs":5}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO scenarios (id, version, status, title, difficulty, topics, suggested_time_limit_minutes, story, starting_entities, starting_connections, traffic_pattern, duration_ms, seed, constraints, given_node_ids, locked_fields, budget_usd, requires_gated_tool_calls, hints, learning_goals, capacity_estimate, reflection, optimal_solution)
VALUES (
  $j$cost-constrained-edge-assistant$j$,
  1,
  'PUBLISHED',
  $j$Cost-Constrained Edge Assistant$j$,
  4,
  $j$["model-routing","agentic-system-design"]$j$::jsonb,
  NULL,
  $j$A consumer app wants an always-on assistant running on-device for millions of users — real volume, a real monthly bill if it's built carelessly. Finance has set a hard budget. Product has set a quality floor. Neither team cares how the engineering gets there, only that both numbers are hit at the same time, every month, not just this one.$j$,
  $j$[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":40}}]$j$::jsonb,
  $j$[]$j$::jsonb,
  $j${"type":"constant","rate":40}$j$::jsonb,
  15000,
  500,
  $j$[{"id":"success-rate","metric":"successRate","comparator":"gte","threshold":0.9,"label":"At least 90% of requests are answered — the quality floor","unit":"%"}]$j$::jsonb,
  $j$["client"]$j$::jsonb,
  $j${"client":["requestRate"]}$j$::jsonb,
  5000,
  FALSE,
  $j$["Always-LLM at full precision clears the quality floor easily. What does it cost at this volume — and does raising Quantization or switching to a cascade mode, on its own, get anywhere close to the budget?","Deployment Target Edge doesn't just change latency — it zeroes the per-token API bill entirely for that node, the real economic argument for it, not just the responsiveness one. Which of the two Model Router targets can actually run there?","A semantic Cache in front of the router skips the model call entirely on a hit, not just the cheap tier. What does stacking that on top of an already-cascaded, already-quantized build actually buy you?","Cost-optimized-cascade and confidence-cascade aren't interchangeable — one of them enforces a real running budget on escalations, the other doesn't. Does that difference show up at this traffic volume?"]$j$::jsonb,
  $j$["No single lever — cascading alone, quantization alone, edge alone, caching alone — clears a genuinely tight budget at real volume. The 90/10 rule and the ~75-85% cost cut §1.10/§1.13 describe both assume the full composition, not one dial turned up.","Edge deployment's real economic argument is zero per-token cost, not just lower latency — a detail easy to miss if you only ever compare quantization levels on the same cloud deployment.","A budget and a quality floor together force a genuinely different architecture than either alone would — a cheap-but-unreliable build fails the floor, a reliable-but-expensive one fails the budget, and only the full stack clears both."]$j$::jsonb,
  $j${"prompt":"Always-LLM, no quantization, cloud deployment, at 40 req/s sustained for a full month — roughly how many requests is that, and at Cloud LLM's baseline ~$2.50/million tokens (800 assumed tokens/request), roughly what does a month of that traffic cost before any optimization at all?","worked":"40 req/s x ~2.63M seconds/month = ~105M requests/month x 800 tokens = ~84 billion tokens/month, at $2.50/million = ~$210,000/month — in the right order of magnitude for what the unoptimized baseline actually costs here. A $5,000 budget is roughly 2% of that; no single lever gets a 40-50x reduction on its own, which is exactly why this scenario needs the full composition, not one dial pushed further."}$j$::jsonb,
  $j${"template":"{{successRate}} success at whatever the Budget row shows this run costing — if quality passed but the bill didn't, or the bill passed but quality slipped, that's the tension this scenario is built around. Both bars only clear together with the full stack: cascade, quantization, edge, and a semantic cache all doing their part."}$j$::jsonb,
  $j${"summary":"A semantic Cache in front of a cost-optimized Model Router cascade, routing to a quantized SLM running on the edge and a quantized LLM as the rare escalation.","editorial":["The topology is Client -> Cache (semantic mode) -> Model Router -> two LLM Calls: an SLM-tier one (INT4 quantization, Edge deployment) wired first, an LLM-tier one (INT8 quantization, Cloud) wired second — the same wiring-order convention every Model Router build uses, SLM/cheap target first.","Edge deployment on the SLM target is what actually gets the bill down by an order of magnitude beyond quantization alone — an on-device call has no per-token API charge at all, the real economic argument this scenario is built to demonstrate rather than assert.","Cost-optimized-cascade (not confidence-cascade) is the mode that actually enforces the budget as traffic scales — it caps what fraction of requests are allowed to escalate to the expensive tier regardless of how many individually look like they'd benefit from it, the literal 'budget-aware threshold' behind the 75-85% cost cut this pillar's research describes.","A common near-miss: quantizing and cascading but leaving deployment on Cloud, or skipping the semantic Cache — either one alone still leaves the bill multiple times over budget at this volume, even though the architecture 'looks' optimized."],"entities":[{"id":"client","type":"client","label":"Client","position":{"x":80,"y":220},"config":{"requestRate":40,"keyPoolSize":30}},{"id":"cache1","type":"cache","label":"Cache","position":{"x":340,"y":220},"config":{"capacity":30,"cachingMode":"semantic","semanticHitRate":0.3}},{"id":"router1","type":"model_router","label":"Model Router","position":{"x":600,"y":220},"config":{"mode":"cost_optimized_cascade"}},{"id":"slm1","type":"llm_call","label":"LLM Call (SLM, Edge)","position":{"x":860,"y":100},"config":{"tier":"slm","quantization":"int4","deploymentTarget":"edge","hallucinationRate":0.03,"schemaFailureRate":0.02}},{"id":"llm1","type":"llm_call","label":"LLM Call (LLM, Cloud)","position":{"x":860,"y":340},"config":{"tier":"llm","quantization":"int8","hallucinationRate":0.03,"schemaFailureRate":0.02}}],"connections":[{"source":"client","target":"cache1","latencyMs":5},{"source":"cache1","target":"router1","latencyMs":5},{"source":"router1","target":"slm1","latencyMs":5},{"source":"router1","target":"llm1","latencyMs":5}]}$j$::jsonb
)
ON CONFLICT (id) DO NOTHING;
